import type {
  SummaryGenerationRequest,
  SummaryGenerationResult,
  SummaryCoverageRequest,
  SummaryCoverageResult,
} from "../../shared/domain";
import { summaryCoveragePayloadSchema } from "../../shared/schemas";
import { sourceMessagesHash } from "../../shared/source-hash";
import type { JobContext } from "../jobs/job-manager";
import { GenerationService } from "./generation-service";
import { SUMMARY_COVERAGE_PROMPT } from "../../shared/summary-prompts";
import { summaryProviderMessages } from "../../shared/summary-protocol";
import { parseSummaryPayload } from "./summary-output";
import { parseConfiguredProviderJson } from "./business-regex";
import { BATCH_OVERVIEW_REQUIRED_CONTENT, batchOverviewPayloadSchema, batchOverviewRequestSchema,
  type BatchOverviewRequest, type BatchOverviewResult } from "../../shared/batch-overview";

export class SummaryService {
  constructor(private readonly generation: GenerationService) {}

  async generateBatchOverview(request: BatchOverviewRequest, context: JobContext): Promise<BatchOverviewResult> {
    batchOverviewRequestSchema.parse(request);
    if (await sourceMessagesHash(request.messages) !== request.batch.sourceHash) {
      throw Object.assign(new Error("Batch summary source messages changed."), { statusCode: 400 });
    }
    context.report(0.1, "Waiting for batch summary API");
    const generated = await this.generation.run({
      workflow: "summary", group: request.generationGroup, policy: request.failoverPolicy,
      resumeAfterEndpointId: request.resumeAfterEndpointId, context,
      messages: [...request.promptMessages, { role: "system",
        content: BATCH_OVERVIEW_REQUIRED_CONTENT }],
    });
    if (generated.decisionRequired) return {
      outcome: "decision_required", attempts: generated.attempts, decisionRequired: generated.decisionRequired,
    };
    if (generated.state !== "succeeded" || !generated.value) {
      throw new Error(generated.message ?? "Batch summary generation failed.");
    }
    const parsed = batchOverviewPayloadSchema.parse(await parseConfiguredProviderJson(generated.value, "批次总结", "content", request.businessRegex, context.signal));
    context.report(0.99, "Validated batch summary");
    return { outcome: "completed", content: parsed.content, attempts: generated.attempts };
  }

  async checkCoverage(request: SummaryCoverageRequest, context: JobContext): Promise<SummaryCoverageResult> {
    if (request.messages.map((message) => message.id).join("\0") !== request.batch.messageIds.join("\0")
      || await sourceMessagesHash(request.messages) !== request.batch.sourceHash) {
      throw Object.assign(new Error("Coverage source messages changed."), { statusCode: 400 });
    }
    context.report(0.1, "Checking summary coverage");
    const generated = await this.generation.run({
      workflow: "summary", group: request.generationGroup, policy: request.failoverPolicy,
      resumeAfterEndpointId: request.resumeAfterEndpointId, context,
      messages: [
        { role: "system", content: SUMMARY_COVERAGE_PROMPT },
        ...request.promptMessages,
        { role: "user", content: JSON.stringify({
          regions: request.messages.map((message, index) => ({ region: index + 1, text: message.content })),
          existingMemories: request.existingSlices,
        }) },
      ],
    });
    if (generated.decisionRequired) return {
      outcome: "decision_required", findings: [], attempts: generated.attempts, decisionRequired: generated.decisionRequired,
    };
    if (generated.state !== "succeeded" || !generated.value) {
      throw new Error(generated.message ?? "Coverage generation failed.");
    }
    const parsed = summaryCoveragePayloadSchema.parse(await parseConfiguredProviderJson(generated.value, "总结覆盖检查", "findings", request.businessRegex, context.signal));
    if (parsed.findings.some((finding) => finding.region > request.messages.length)) {
      throw new Error("Coverage response references an unavailable review region.");
    }
    context.report(0.99, `Validated ${parsed.findings.length} coverage suggestions`);
    return { outcome: "completed", findings: parsed.findings, attempts: generated.attempts };
  }

  async generate(
    request: SummaryGenerationRequest,
    context: JobContext,
  ): Promise<SummaryGenerationResult> {
    const suppliedIds = request.messages.map((message) => message.id);
    if (suppliedIds.join("\0") !== request.batch.messageIds.join("\0")) {
      throw Object.assign(new Error("Summary batch message IDs do not match the supplied messages."), {
        statusCode: 400,
      });
    }
    if (await sourceMessagesHash(request.messages) !== request.batch.sourceHash) {
      throw Object.assign(new Error("Summary batch source hash does not match the supplied messages."), {
        statusCode: 400,
      });
    }
    const providerMessages = summaryProviderMessages(request);
    context.report(0.1, "Waiting for summary API");
    const generated = await this.generation.run({
      workflow: "summary",
      group: request.generationGroup,
      policy: request.failoverPolicy,
      resumeAfterEndpointId: request.resumeAfterEndpointId,
      messages: providerMessages,
      context,
    });
    if (generated.decisionRequired) {
      return {
        outcome: "decision_required",
        slices: [],
        attempts: generated.attempts,
        decisionRequired: generated.decisionRequired,
      };
    }
    if (generated.state !== "succeeded" || !generated.value) {
      throw Object.assign(new Error(generated.message ?? "All generation endpoints failed."), {
        statusCode: 502,
        code: "GENERATION_ENDPOINTS_FAILED",
      });
    }
    context.report(0.82, "Validating summary slices");
    let parsed: ReturnType<typeof parseSummaryPayload>;
    try {
      parsed = parseSummaryPayload(await parseConfiguredProviderJson(generated.value, "总结切片", "summaries", request.businessRegex, context.signal));
    } catch (error) {
      throw Object.assign(new Error(error instanceof Error ? error.message : "Invalid summary response."), {
        statusCode: 502,
        code: "INVALID_SUMMARY_RESPONSE",
      });
    }
    const slices = parsed.summaries.map((slice) => ({
      ...slice,
      tags: [...new Set(slice.tags)],
    }));
    if (!request.extractAttributes && slices.some((slice) => slice.continuity)) {
      throw new Error("Temporal/knowledge extraction is disabled; omit continuity attributes.");
    }
    context.report(0.99, `Validated ${slices.length} summary slices`
      + (parsed.normalizedFields ? `; 兼容规范化 ${parsed.normalizedFields} 个格式字段` : ""));
    return { outcome: "completed", slices, attempts: generated.attempts };
  }
}
