import { businessRegex, splitBusinessText, type BusinessRegexSettings } from "./business-regex";
import type { ExtractionContextPolicy, MemoryRow, MemoryTypeDefinition } from "./domain";
export type AliasIndex = Record<string, string[]>;

export function declaredAliases(row: MemoryRow, types: MemoryTypeDefinition[], rules: BusinessRegexSettings = {}): string[] {
  const type = types.find((item) => item.id === row.typeId);
  const columns = type?.columns.filter((column) => businessRegex("aliasName", rules).test(column.name)
    || businessRegex("aliasId", rules).test(column.id)) ?? [];
  return [...new Set([...(row.aliases ?? []), ...columns.flatMap((column) => {
    const value = row.values[column.id];
    if (Array.isArray(value)) return value.filter((item): item is string => typeof item === "string").map((item) => item.trim());
    return typeof value === "string" ? splitBusinessText(value, "aliasSeparator", rules).map((item) => item.trim()) : [];
  }).filter(Boolean)])];
}

export function selectExtractionRows(
  rows: MemoryRow[], types: MemoryTypeDefinition[], query: string, policy?: ExtractionContextPolicy, aliases?: AliasIndex,
) {
  if (!policy?.enabled) return { rows, omitted: [] as string[], detailCharacters: JSON.stringify(rows).length };
  const text = query.toLocaleLowerCase();
  const scored = rows.map((row, index) => ({
    row, index,
    score: [row.dataName, ...(aliases?.[row.id] ?? declaredAliases(row, types))].some((name) => name.length > 1 && text.includes(name.toLocaleLowerCase()))
      ? 100 : row.keywords.filter((word) => word.length > 1 && text.includes(word.toLocaleLowerCase())).length,
  })).filter((item) => item.score > 0).sort((a, b) => b.score - a.score || a.index - b.index);
  const selected: MemoryRow[] = [];
  const ids = new Set<string>();
  let detailCharacters = 0;
  const add = (row: MemoryRow) => {
    const size = JSON.stringify(row).length;
    if (ids.has(row.id) || selected.length >= policy.maxRows || detailCharacters + size > policy.maxCharacters) return false;
    selected.push(row);
    ids.add(row.id);
    detailCharacters += size;
    return true;
  };
  for (const { row } of scored) add(row);
  const referencedText = selected.map((row) => JSON.stringify(row.values)).join("\n");
  let related = 0;
  for (const row of rows) {
    if (related >= policy.relatedRows) break;
    if (referencedText.includes(row.id) || row.dataName.length > 1 && referencedText.includes(row.dataName)) {
      if (add(row)) related++;
    }
  }
  return { rows: selected, omitted: rows.filter((row) => !ids.has(row.id)).map((row) => row.id), detailCharacters };
}

export function extractionNameCollision(rows: MemoryRow[], types: MemoryTypeDefinition[], typeId: string, name: string, exceptId?: string, aliases?: AliasIndex) {
  const normalized = name.trim().toLocaleLowerCase();
  return rows.find((row) => row.typeId === typeId && row.id !== exceptId
    && [row.dataName, ...(aliases?.[row.id] ?? declaredAliases(row, types))].some((value) => value.trim().toLocaleLowerCase() === normalized));
}
