import { Worker } from "node:worker_threads";
import path from "node:path";
import { executeBusinessTask, needsBusinessWorker, type BusinessTask, type BusinessTaskRequest, type BusinessResult } from "../../shared/business-regex-tasks";
import type { BusinessRegexSettings } from "../../shared/business-regex";

export function runBusinessTask<K extends BusinessTask>(request: BusinessTaskRequest<K>, signal?: AbortSignal): Promise<BusinessResult<K>> {
  signal?.throwIfAborted();
  if (!needsBusinessWorker(request)) return Promise.resolve(executeBusinessTask(request));
  const worker = new Worker(path.join(__dirname, "business-regex-worker.cjs"), {
    workerData: request, resourceLimits: { maxOldGenerationSizeMb: 128 },
  });
  return new Promise((resolve, reject) => {
    let settled = false;
    const finish = (complete: () => void) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      signal?.removeEventListener("abort", abort);
      void worker.terminate();
      complete();
    };
    const abort = () => finish(() => reject(signal?.reason ?? new Error("业务解析已取消。")));
    const timer = setTimeout(() => finish(() => reject(new Error("业务解析执行超过 2 秒，已终止。"))), 2000);
    signal?.addEventListener("abort", abort, { once: true });
    worker.once("message", (data: { ok: boolean; result: BusinessResult<K>; error?: string }) => {
      finish(() => { if (data.ok) resolve(data.result); else reject(new Error(data.error ?? "业务解析执行失败。")); });
    });
    worker.once("error", (error) => finish(() => reject(error)));
    worker.once("exit", () => finish(() => reject(new Error("业务解析线程提前结束。"))));
    if (signal?.aborted) abort();
  });
}
export function parseConfiguredProviderJson(raw: string, label: string, requiredKey: string | undefined, rules: BusinessRegexSettings = {}, signal?: AbortSignal) {
  return runBusinessTask({ task: "provider", args: [raw, label, requiredKey, rules] }, signal);
}
