import { z } from "zod";

export const BUSINESS_REGEX_RULES = [
  { id: "aliasName", group: "人物与资料", name: "别名列名称", pattern: "^(别名|别称|aliases?|alternate_names?)$", flags: "i", usage: "识别作为别名使用的表格列名称。" },
  { id: "aliasId", group: "人物与资料", name: "别名列标识", pattern: "^(aliases?|alternate_names?)$", flags: "i", usage: "识别作为别名使用的表格列 ID。" },
  { id: "aliasSeparator", group: "人物与资料", name: "别名分隔符", pattern: "[\\n/、,，;；]", flags: "", usage: "把文本列拆成多个别名；显式 aliases 数组不受影响。" },
  { id: "reasoningClosed", group: "模型输出", name: "完整思考块", pattern: "<(thinking|think)>[\\s\\S]*?<\\/\\1>", flags: "gi", usage: "解析 JSON 前移除匹配的思考块，避免把思考草稿当作最终结果。" },
  { id: "reasoningOpen", group: "模型输出", name: "未闭合思考块", pattern: "<(thinking|think)>", flags: "i", usage: "完整思考块移除后，从残留开标签处截断。建议和完整思考块规则一起调整。" },
  { id: "sceneEmpty", group: "连续性召回", name: "无有效场景", pattern: "^(?:未知|未明确|无|-)$", flags: "u", usage: "匹配这些地点或在场角色文本时，不创建场景召回。" },
  { id: "planDone", group: "连续性召回", name: "已结束事项", pattern: "已完成|已取消", flags: "", usage: "匹配计划条目名称时跳过该事项。" },
  { id: "planPending", group: "连续性召回", name: "未完成事项", pattern: "未解决|待办|未完成|约定|计划|承诺", flags: "", usage: "匹配计划条目名称时创建召回查询。" },
  { id: "querySeparator", group: "召回查询", name: "补充查询分句", pattern: "[\\n。！？!?]+", flags: "u", usage: "从已有查询拆出补充查询片段，不生成新剧情。" },
  { id: "coverageWords", group: "总结覆盖", name: "词语提取", pattern: "[\\p{L}\\p{N}]+", flags: "gu", usage: "提取用于本地覆盖率及相似度比较的词语。" },
  { id: "coverageHan", group: "总结覆盖", name: "汉字识别", pattern: "\\p{Script=Han}", flags: "u", usage: "匹配的词语按相邻两字拆分后比较。" },
] as const;
export type BusinessRegexId = typeof BUSINESS_REGEX_RULES[number]["id"];
export const businessRegexValueSchema = z.object({
  pattern: z.string().max(4000), flags: z.string().max(8), enabled: z.boolean().default(true),
}).strict().superRefine((value, context) => {
  try { new RegExp(value.pattern, value.flags); }
  catch (error) { context.addIssue({ code: "custom", message: `正则无法编译：${error instanceof Error ? error.message : String(error)}` }); }
});
export const businessRegexSettingsSchema = z.partialRecord(z.enum(BUSINESS_REGEX_RULES.map((rule) => rule.id)), businessRegexValueSchema);
export type BusinessRegexSettings = z.infer<typeof businessRegexSettingsSchema>;
export function businessRegex(id: BusinessRegexId, settings: BusinessRegexSettings = {}): RegExp {
  const rule = settings[id] ?? BUSINESS_REGEX_RULES.find((entry) => entry.id === id)!;
  return new RegExp("enabled" in rule && !rule.enabled ? "(?!)" : rule.pattern, rule.flags);
}

/** Split at complete matches; capture groups describe the separator, not output parts. */
export function splitBusinessText(text: string, id: BusinessRegexId, settings: BusinessRegexSettings = {}): string[] {
  const separator = businessRegex(id, settings);
  const all = new RegExp(separator.source, separator.flags.includes("g") ? separator.flags : `${separator.flags}g`);
  const parts: string[] = [];
  let start = 0;
  for (const match of text.matchAll(all)) {
    parts.push(text.slice(start, match.index));
    start = match.index + match[0].length;
  }
  parts.push(text.slice(start));
  return parts;
}
