import type { PromptMessageInput, SummaryGenerationRequest } from "./domain";
import { CONTINUITY_EXTRACTION_GUIDE } from "./continuity";

export const SUMMARY_OUTPUT_PROTOCOL = `只输出一个 JSON 对象，不加代码块、说明或思考过程：
字符串值内如需引用文字，请使用中文引号“”，不要使用英文双引号；字符串值内不要直接换行。
{"summaries":[{"timestamp":"时间","title":"标题","content":"正文","tags":["标签"]}]}
- summaries 包含 1～50 条记录；title、content、tags 用中文。
- timestamp 是故事内时间文本，保留原文历法、纪元和已有精度，例如“辉轮历270年”“协定历270年”“271-04-07T08”“星海历第七周期”。这些不同历法中的年号不能相互替换。
- 允许时间区间、相对时间和模糊描述，例如“新元三年冬至次年春”“大约三天后”。不强制公历格式，不补零、不截掉分钟，不擅自换算历法；没有时间依据时写“未知”。

虚构格式示例，不是故事事实：
{"summaries":[{"timestamp":"2087-04","title":"洛禾暂存罗盘","content":"洛禾在春季测绘前把旧罗盘交给钟表匠温砚保管。温砚答应只检查外壳、不拆内部齿轮；双方还没有约定取回的日期。","tags":["洛禾","温砚","旧罗盘"]}]}`;

export function summaryProviderMessages(request: Pick<SummaryGenerationRequest, "promptMessages" | "extractAttributes">): PromptMessageInput[] {
  return [
    ...request.promptMessages,
    ...(request.extractAttributes ? [{ role: "system" as const, content: CONTINUITY_EXTRACTION_GUIDE }] : []),
    { role: "user", content: SUMMARY_OUTPUT_PROTOCOL + (request.extractAttributes
      ? "\n- 每条记录可以另外附带上面说明的 continuity 对象。"
      : "\n- 每条记录只有 timestamp、title、content、tags 四个字段；不确定性和归属写进 content。") },
  ];
}
