import type {
  PromptMessageInput,
  StatusPatchOperation,
  StatusUpdateRequest,
  StatusUpdateResult,
} from "../../shared/domain";
import { statusProviderPayloadSchema } from "../../shared/schemas";
import { applyStatusOperations, statusStateHash } from "../../shared/status-core";
import type { JobContext } from "../jobs/job-manager";
import { GenerationService } from "./generation-service";
import { parseConfiguredProviderJson } from "./business-regex";
import { parseProviderJsonObject } from "./provider-json";
import { STATUS_OUTPUT_PROTOCOL, statusValidationNote } from "../../shared/status-prompts";

export { STATUS_OUTPUT_PROTOCOL };

export function parseStatusProviderOutput(raw: string): ReturnType<typeof statusProviderPayloadSchema.parse> {
  return statusProviderPayloadSchema.parse(parseProviderJsonObject(raw, "状态", "operations"));
}

export class StatusService {
  constructor(private readonly generation: GenerationService) {}

  async update(request: StatusUpdateRequest, context: JobContext): Promise<StatusUpdateResult> {
    if (await statusStateHash(request.baseState) !== request.baseStateHash) {
      throw Object.assign(new Error("Status base hash does not match the supplied state."), {
        statusCode: 400,
        code: "STATUS_BASE_HASH_MISMATCH",
      });
    }
    const providerMessages: PromptMessageInput[] = [
      ...request.promptMessages,
      ...(request.validation.rules.length || request.validation.unknownFields === "reject"
        ? [{ role: "system" as const, content: statusValidationNote(request.validation) }]
        : []),
      { role: "user", content: STATUS_OUTPUT_PROTOCOL },
    ];
    context.report(0.1, "Waiting for status API");
    const generated = await this.generation.run({
      workflow: "status",
      group: request.generationGroup,
      policy: request.failoverPolicy,
      resumeAfterEndpointId: request.resumeAfterEndpointId,
      messages: providerMessages,
      context,
    });
    if (generated.decisionRequired) {
      return {
        outcome: "decision_required",
        operations: [],
        attempts: generated.attempts,
        decisionRequired: generated.decisionRequired,
      };
    }
    if (generated.state !== "succeeded" || !generated.value) {
      throw Object.assign(new Error(generated.message ?? "All status generation endpoints failed."), {
        statusCode: 502,
        code: "STATUS_ENDPOINTS_FAILED",
      });
    }
    context.report(0.82, "Validating status update");
    let parsed: ReturnType<typeof parseStatusProviderOutput>;
    try {
      parsed = statusProviderPayloadSchema.parse(await parseConfiguredProviderJson(generated.value, "状态", "operations", request.businessRegex, context.signal));
    } catch (error) {
      throw Object.assign(new Error(error instanceof Error ? error.message : "Invalid status response."), {
        statusCode: 502,
        code: "INVALID_STATUS_RESPONSE",
      });
    }
    const evidenceMessageIds = request.messages.map((message) => message.id);
    const operations: StatusPatchOperation[] = parsed.operations.map((operation) => ({
      ...operation,
      evidenceMessageIds: [...evidenceMessageIds],
    }));
    const state = applyStatusOperations({
      baseState: request.baseState,
      operations,
      evidenceMessageIds,
      validation: request.validation,
    });
    const stateHash = await statusStateHash(state);
    context.report(0.99, `Validated ${operations.length} status operations`);
    return {
      outcome: "completed",
      operations,
      state,
      stateHash,
      attempts: generated.attempts,
    };
  }
}
