import { createHash, randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

import * as lancedb from "@lancedb/lancedb";
import type { Connection, Table } from "@lancedb/lancedb";

import type {
  RetrievalCollection,
  RetrievalCollectionStats,
  RetrievalDocument,
  RetrievalDocumentInput,
  RetrievalDocumentManifestResult,
  VectorState,
} from "../../shared/domain";
import { retrievalCollectionSchema } from "../../shared/schemas";
import type { RankedRetrievalDocument } from "./fusion";

const DOCUMENT_TABLE = "documents";
const VECTOR_INDEX_THRESHOLD = 10_000;
const WORD_SEGMENTER = new Intl.Segmenter("zh", { granularity: "word" });

interface Manifest {
  formatVersion: 1;
  collections: RetrievalCollection[];
}

interface DocumentRow extends Record<string, unknown> {
  document_id: string;
  collection_id: string;
  source_type: string;
  source_id: string;
  text: string;
  search_text: string;
  tags_json: string;
  metadata_json: string;
  content_hash: string;
  vector_state: VectorState;
  created_at: string;
  updated_at: string;
}

function hash(value: string): string {
  return createHash("sha256").update(value).digest("hex");
}

function sqlString(value: string): string {
  return `'${value.replaceAll("'", "''")}'`;
}

function inFilter(column: string, values: string[]): string {
  if (values.length === 0) return "false";
  return `${column} IN (${values.map(sqlString).join(", ")})`;
}

// These columns are always written by documentRow; unreadable values mean the index is damaged.
function storedJson(value: unknown, column: string, documentId: unknown): unknown {
  try {
    return JSON.parse(String(value));
  } catch {
    throw new Error(`检索文档 ${String(documentId)} 的 ${column} 已损坏，请从源世界书修复索引。`);
  }
}

function storedTags(row: Record<string, unknown>): string[] {
  const parsed = storedJson(row.tags_json, "tags_json", row.document_id);
  if (!Array.isArray(parsed)) throw new Error(`检索文档 ${String(row.document_id)} 的 tags_json 不是数组，请从源世界书修复索引。`);
  return parsed.map(String);
}

function storedMetadata(row: Record<string, unknown>): Record<string, unknown> {
  const parsed = storedJson(row.metadata_json, "metadata_json", row.document_id);
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error(`检索文档 ${String(row.document_id)} 的 metadata_json 不是对象，请从源世界书修复索引。`);
  }
  return parsed as Record<string, unknown>;
}

function cjkNgrams(value: string): string[] {
  const compact = value.replace(/[^\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}]/gu, "");
  const characters = [...compact];
  const grams: string[] = [];
  for (const size of [2, 3]) {
    for (let index = 0; index + size <= characters.length; index += 1) {
      grams.push(characters.slice(index, index + size).join(""));
    }
  }
  return grams;
}

export function lexicalText(value: string): string {
  const tokens: string[] = [];
  for (const segment of WORD_SEGMENTER.segment(value.normalize("NFKC"))) {
    const token = segment.segment.trim().toLocaleLowerCase();
    if (token && (segment.isWordLike || /[\p{L}\p{N}]/u.test(token))) tokens.push(token);
  }
  tokens.push(...cjkNgrams(value));
  return [...new Set(tokens)].join(" ");
}

function toDocument(row: Record<string, unknown>): RetrievalDocument {
  return {
    documentId: String(row.document_id),
    collectionId: String(row.collection_id),
    sourceType: String(row.source_type),
    sourceId: String(row.source_id),
    text: String(row.text),
    tags: storedTags(row),
    metadata: storedMetadata(row),
    contentHash: String(row.content_hash),
    vectorState: String(row.vector_state) as VectorState,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

function documentRow(document: RetrievalDocument): DocumentRow {
  return {
    document_id: document.documentId,
    collection_id: document.collectionId,
    source_type: document.sourceType,
    source_id: document.sourceId,
    text: document.text,
    search_text: lexicalText(document.text),
    tags_json: JSON.stringify(document.tags),
    metadata_json: JSON.stringify(document.metadata),
    content_hash: document.contentHash,
    vector_state: document.vectorState,
    created_at: document.createdAt,
    updated_at: document.updatedAt,
  };
}

function vectorTableName(embeddingSpaceId: string): string {
  return `vectors_${hash(embeddingSpaceId).slice(0, 24)}`;
}

export class RetrievalStore {
  private connection: Connection | null = null;
  private initializePromise: Promise<void> | null = null;
  private writeChain: Promise<unknown> = Promise.resolve();
  private readonly databaseDirectory: string;
  private readonly manifestPath: string;

  constructor(private readonly rootDirectory: string) {
    this.databaseDirectory = path.join(rootDirectory, "lancedb");
    this.manifestPath = path.join(rootDirectory, "collections.json");
  }

  async initialize(): Promise<void> {
    if (this.connection) return;
    if (!this.initializePromise) this.initializePromise = this.initializeInternal();
    try {
      await this.initializePromise;
    } finally {
      this.initializePromise = null;
    }
  }

  async listCollections(): Promise<RetrievalCollection[]> {
    await this.initialize();
    return structuredClone((await this.readManifest()).collections);
  }

  async createCollection(
    input: Pick<RetrievalCollection, "id" | "name" | "description" | "embeddingSpaceId" | "dimensions">,
  ): Promise<RetrievalCollection> {
    return this.serialize(async () => {
      const manifest = await this.readManifest();
      if (manifest.collections.some((collection) => collection.id === input.id)) {
        throw Object.assign(new Error(`Collection already exists: ${input.id}`), { statusCode: 409 });
      }
      const incompatibleSpace = manifest.collections.find((collection) =>
        collection.embeddingSpaceId === input.embeddingSpaceId
        && collection.dimensions !== input.dimensions);
      if (incompatibleSpace) {
        throw Object.assign(
          new Error(`Embedding space ${input.embeddingSpaceId} already uses ${incompatibleSpace.dimensions} dimensions.`),
          { statusCode: 409 },
        );
      }
      const now = new Date().toISOString();
      const collection: RetrievalCollection = { ...input, createdAt: now, updatedAt: now };
      manifest.collections.push(collection);
      await this.writeManifest(manifest);
      return structuredClone(collection);
    });
  }

  async deleteCollection(collectionId: string): Promise<boolean> {
    return this.serialize(async () => {
      const manifest = await this.readManifest();
      if (!manifest.collections.some((collection) => collection.id === collectionId)) return false;
      const documents = await this.documentsTable();
      for await (const batch of this.documentBatches([collectionId], 500)) {
        await this.deleteVectors(batch.map((document) => document.documentId));
      }
      await documents.delete(`collection_id = ${sqlString(collectionId)}`);
      manifest.collections = manifest.collections.filter((collection) => collection.id !== collectionId);
      await this.writeManifest(manifest);
      return true;
    });
  }

  async prepareUpsert(inputs: RetrievalDocumentInput[]): Promise<{
    documents: RetrievalDocument[];
    needsEmbedding: RetrievalDocument[];
    created: number;
    updated: number;
    unchanged: number;
  }> {
    return this.serialize(async () => {
      const manifest = await this.readManifest();
      const knownCollections = new Set(manifest.collections.map((collection) => collection.id));
      for (const input of inputs) {
        if (!knownCollections.has(input.collectionId)) {
          throw Object.assign(new Error(`Unknown retrieval collection: ${input.collectionId}`), { statusCode: 404 });
        }
      }

      const ids = inputs.map((input) => input.documentId
        ?? `doc_${hash(`${input.collectionId}\0${input.sourceType}\0${input.sourceId}`).slice(0, 48)}`);
      if (new Set(ids).size !== ids.length) {
        throw Object.assign(new Error("A document batch contains duplicate identities."), { statusCode: 400 });
      }
      const existing = new Map((await this.getDocuments(ids)).map((document) => [document.documentId, document]));
      const now = new Date().toISOString();
      const documents: RetrievalDocument[] = [];
      const needsEmbedding: RetrievalDocument[] = [];
      let created = 0;
      let updated = 0;
      let unchanged = 0;

      for (const [index, input] of inputs.entries()) {
        const documentId = ids[index]!;
        const previous = existing.get(documentId);
        const contentHash = hash(input.text);
        const sameText = previous?.contentHash === contentHash;
        const sameIdentity = previous?.collectionId === input.collectionId
          && previous.sourceType === input.sourceType
          && previous.sourceId === input.sourceId;
        const reusableVector = sameText && sameIdentity;
        const sameDocument = reusableVector
          && JSON.stringify(previous.tags) === JSON.stringify(input.tags)
          && JSON.stringify(previous.metadata) === JSON.stringify(input.metadata);
        const document: RetrievalDocument = {
          ...input,
          documentId,
          contentHash,
          vectorState: reusableVector && previous ? previous.vectorState : "pending",
          createdAt: previous?.createdAt ?? now,
          updatedAt: sameDocument && previous ? previous.updatedAt : now,
        };
        documents.push(document);
        if (!previous) created += 1;
        else if (sameDocument) unchanged += 1;
        else updated += 1;
        if (!previous || !reusableVector || previous.vectorState !== "ready") needsEmbedding.push(document);
      }

      const table = await this.documentsTable();
      await table.mergeInsert("document_id")
        .whenMatchedUpdateAll()
        .whenNotMatchedInsertAll()
        .execute(documents.map(documentRow));
      if (needsEmbedding.length > 0) {
        await this.deleteVectors(needsEmbedding.map((document) => document.documentId));
      }
      return { documents, needsEmbedding, created, updated, unchanged };
    });
  }

  /** Find legacy ready documents whose expected vector is absent or belongs elsewhere.
   * This only invalidates derived data; embedding remains an explicit index job.
   */
  async reconcileVectorState(collectionIds: string[], signal?: AbortSignal): Promise<number> {
    return this.serialize(async () => {
      const collections = new Map((await this.listCollections()).map((item) => [item.id, item]));
      const documentsTable = await this.documentsTable();
      let invalidated = 0;
      for await (const batch of this.documentBatches(collectionIds, 100, ["ready"])) {
        signal?.throwIfAborted();
        const valid = new Set<string>();
        const spaces = new Set(batch.map((item) => collections.get(item.collectionId)?.embeddingSpaceId));
        for (const space of spaces) {
          if (!space) continue;
          const vectors = await this.openVectorTable(space);
          if (!vectors) continue;
          const expected = new Map(batch.filter((item) => collections.get(item.collectionId)?.embeddingSpaceId === space)
            .map((item) => [item.documentId, item]));
          const rows = await vectors.query().where(inFilter("document_id", [...expected.keys()]))
            .select(["document_id", "collection_id", "source_id", "content_hash"])
            .limit(expected.size).toArray();
          for (const row of rows) {
            const document = expected.get(String(row.document_id));
            if (document && document.collectionId === String(row.collection_id)
              && document.sourceId === String(row.source_id) && document.contentHash === String(row.content_hash)) {
              valid.add(document.documentId);
            }
          }
        }
        signal?.throwIfAborted();
        const stale = batch.filter((item) => !valid.has(item.documentId)).map((item) => item.documentId);
        if (!stale.length) continue;
        // Mark pending before deletion: a failed cleanup cannot leave a stale vector usable.
        await documentsTable.update({ where: inFilter("document_id", stale),
          values: { vector_state: "pending", updated_at: new Date().toISOString() } });
        await this.deleteVectors(stale);
        invalidated += stale.length;
      }
      return invalidated;
    });
  }

  async markVectorState(documentIds: string[], state: VectorState): Promise<void> {
    if (documentIds.length === 0) return;
    await this.serialize(async () => {
      const table = await this.documentsTable();
      await table.update({
        where: inFilter("document_id", documentIds),
        values: { vector_state: state, updated_at: new Date().toISOString() },
      });
    });
  }

  async upsertVectors(options: {
    embeddingSpaceId: string;
    dimensions: number;
    documents: RetrievalDocument[];
    vectors: number[][];
  }): Promise<void> {
    if (options.documents.length !== options.vectors.length) {
      throw new Error("Embedding response count does not match the document batch.");
    }
    await this.serialize(async () => {
      const rows = options.documents.map((document, index) => {
        const vector = options.vectors[index]!;
        if (vector.length !== options.dimensions || vector.some((value) => !Number.isFinite(value))) {
          throw new Error(`Embedding dimension mismatch for ${document.documentId}.`);
        }
        return {
          document_id: document.documentId,
          collection_id: document.collectionId,
          source_id: document.sourceId,
          content_hash: document.contentHash,
          vector,
        };
      });
      const existingTable = await this.openVectorTable(options.embeddingSpaceId);
      const table = existingTable ?? await this.vectorTable(options.embeddingSpaceId, rows);
      if (existingTable) {
        await table.mergeInsert("document_id")
          .whenMatchedUpdateAll()
          .whenNotMatchedInsertAll()
          .execute(rows);
      }
      await this.ensureVectorIndex(table);
    });
  }

  async getDocuments(documentIds: string[]): Promise<RetrievalDocument[]> {
    if (documentIds.length === 0) return [];
    const table = await this.documentsTable();
    const rows = await table.query()
      .where(inFilter("document_id", documentIds))
      .limit(documentIds.length)
      .toArray();
    return rows.map((row) => toDocument(row as Record<string, unknown>));
  }

  async scanDocuments(collectionIds: string[], batchSize = 100): Promise<RetrievalDocument[]> {
    const documents: RetrievalDocument[] = [];
    for await (const batch of this.documentBatches(collectionIds, batchSize)) documents.push(...batch);
    return documents;
  }

  async documentManifest(collectionId: string, afterDocumentId?: string, limit = 500): Promise<RetrievalDocumentManifestResult> {
    const table = await this.documentsTable();
    const filters = [`collection_id = ${sqlString(collectionId)}`];
    if (afterDocumentId) filters.push(`document_id > ${sqlString(afterDocumentId)}`);
    const rows = await table.query()
      .select(["document_id", "collection_id", "source_type", "source_id"])
      .where(filters.join(" AND "))
      .orderBy({ columnName: "document_id", ascending: true })
      .limit(limit)
      .toArray();
    const documents = rows.map((row) => ({
      documentId: String(row.document_id),
      collectionId: String(row.collection_id),
      sourceType: String(row.source_type),
      sourceId: String(row.source_id),
    }));
    return { documents, ...(documents.length === limit ? { nextAfterDocumentId: documents.at(-1)!.documentId } : {}) };
  }

  async *documentBatches(
    collectionIds: string[],
    batchSize = 100,
    vectorStates: VectorState[] = [],
  ): AsyncGenerator<RetrievalDocument[]> {
    const table = await this.documentsTable();
    let lastDocumentId: string | undefined;
    while (true) {
      const filters = [inFilter("collection_id", collectionIds)];
      if (vectorStates.length > 0) filters.push(inFilter("vector_state", vectorStates));
      if (lastDocumentId) filters.push(`document_id > ${sqlString(lastDocumentId)}`);
      const rows = await table.query()
        .where(filters.join(" AND "))
        .orderBy({ columnName: "document_id", ascending: true })
        .limit(batchSize)
        .toArray();
      if (rows.length === 0) return;
      yield rows.map((row) => toDocument(row as Record<string, unknown>));
      if (rows.length < batchSize) return;
      lastDocumentId = String((rows.at(-1) as Record<string, unknown>).document_id);
    }
  }

  async searchBm25(
    query: string,
    collectionIds: string[],
    limit: number,
    excludeSourceIds: string[] = [],
  ): Promise<RankedRetrievalDocument[]> {
    const table = await this.documentsTable();
    const filters = [inFilter("collection_id", collectionIds)];
    if (excludeSourceIds.length > 0) {
      filters.push(`NOT (${inFilter("source_id", excludeSourceIds)})`);
    }
    const rows = await table.search(lexicalText(query), "fts", "search_text")
      .where(filters.join(" AND "))
      .limit(limit)
      .toArray();
    return rows.map((row) => ({
      document: toDocument(row as Record<string, unknown>),
      score: Number((row as Record<string, unknown>)._score ?? 0),
    }));
  }

  async searchVector(options: {
    embeddingSpaceId: string;
    queryVector: number[];
    collectionIds: string[];
    limit: number;
    excludeSourceIds?: string[] | undefined;
  }): Promise<RankedRetrievalDocument[]> {
    const table = await this.openVectorTable(options.embeddingSpaceId);
    if (!table) return [];
    const collections = new Map((await this.listCollections()).map((item) => [item.id, item]));
    const allowedCollections = new Set(options.collectionIds);
    const excludedSources = new Set(options.excludeSourceIds ?? []);
    const filters = [inFilter("collection_id", options.collectionIds)];
    if (options.excludeSourceIds?.length) {
      filters.push(`NOT (${inFilter("source_id", options.excludeSourceIds)})`);
    }
    const rows = await table.vectorSearch(options.queryVector)
      .distanceType("cosine")
      .where(filters.join(" AND "))
      .limit(options.limit)
      .toArray();
    const documentIds = rows.map((row) => String((row as Record<string, unknown>).document_id));
    const documents = new Map((await this.getDocuments(documentIds)).map((document) => [document.documentId, document]));
    return rows.flatMap((row) => {
      const record = row as Record<string, unknown>;
      const document = documents.get(String(record.document_id));
      if (!document
        || document.vectorState !== "ready"
        || !allowedCollections.has(document.collectionId)
        || excludedSources.has(document.sourceId)
        || document.collectionId !== String(record.collection_id)
        || document.sourceId !== String(record.source_id)
        || collections.get(document.collectionId)?.embeddingSpaceId !== options.embeddingSpaceId
        || document.contentHash !== String(record.content_hash)) return [];
      const distance = Number(record._distance ?? 1);
      return [{ document, score: Number.isFinite(distance) ? 1 - distance : 0 }];
    });
  }

  async deleteDocuments(documentIds: string[]): Promise<number> {
    if (documentIds.length === 0) return 0;
    return this.serialize(async () => {
      const existing = await this.getDocuments(documentIds);
      const table = await this.documentsTable();
      await table.delete(inFilter("document_id", documentIds));
      await this.deleteVectors(documentIds);
      return existing.length;
    });
  }

  async collectionStats(collection: RetrievalCollection): Promise<RetrievalCollectionStats> {
    const documents = await this.documentsTable();
    const baseFilter = `collection_id = ${sqlString(collection.id)}`;
    const [count, ready, pending, failed, ambiguous] = await Promise.all([
      documents.countRows(baseFilter),
      documents.countRows(`${baseFilter} AND vector_state = 'ready'`),
      documents.countRows(`${baseFilter} AND vector_state = 'pending'`),
      documents.countRows(`${baseFilter} AND vector_state = 'failed'`),
      documents.countRows(`${baseFilter} AND vector_state = 'ambiguous'`),
    ]);
    const vectors = await this.openVectorTable(collection.embeddingSpaceId);
    const vectorIndex = vectors && (await vectors.listIndices()).some((index) => index.name === "vector_idx")
      ? "hnsw_sq" as const
      : "flat" as const;
    return {
      collection,
      documents: count,
      ready,
      pending,
      failed,
      ambiguous,
      vectorIndex,
      dimensions: collection.dimensions,
    };
  }

  async optimize(): Promise<void> {
    await this.serialize(async () => {
      const documentTable = await this.documentsTable();
      await documentTable.optimize();
      const manifest = await this.readManifest();
      for (const spaceId of new Set(manifest.collections.map((collection) => collection.embeddingSpaceId))) {
        const table = await this.openVectorTable(spaceId);
        if (table) await table.optimize();
      }
    });
  }

  private async initializeInternal(): Promise<void> {
    await mkdir(this.rootDirectory, { recursive: true });
    await mkdir(this.databaseDirectory, { recursive: true });
    const manifest = await this.readManifest();
    this.connection = await lancedb.connect(this.databaseDirectory);
    const tables = await this.connection.tableNames();
    if (!tables.includes(DOCUMENT_TABLE)) {
      const sentinel: DocumentRow = {
        document_id: "schema_sentinel",
        collection_id: "schema_sentinel",
        source_type: "schema",
        source_id: "schema",
        text: "schema",
        search_text: "schema",
        tags_json: "[]",
        metadata_json: "{}",
        content_hash: "schema",
        vector_state: "pending",
        created_at: new Date(0).toISOString(),
        updated_at: new Date(0).toISOString(),
      };
      const table = await this.connection.createTable(DOCUMENT_TABLE, [sentinel]);
      await table.createIndex("search_text", {
        config: lancedb.Index.fts({
          baseTokenizer: "simple",
          stem: false,
          removeStopWords: false,
          asciiFolding: false,
          lowercase: true,
        }),
      });
      await table.createIndex("document_id", { config: lancedb.Index.btree() });
      await table.createIndex("collection_id", { config: lancedb.Index.btree() });
      await table.delete("document_id = 'schema_sentinel'");
    }
    await this.migrateVectorSourceIds(manifest);
  }

  private async migrateVectorSourceIds(manifest: Manifest): Promise<void> {
    const tableNames = new Set(await this.connection!.tableNames());
    const documents = await this.connection!.openTable(DOCUMENT_TABLE);
    for (const spaceId of new Set(manifest.collections.map((collection) => collection.embeddingSpaceId))) {
      const name = vectorTableName(spaceId);
      if (!tableNames.has(name)) continue;
      const vectors = await this.connection!.openTable(name);
      const schema = await vectors.schema();
      if (!schema.fields.some((field) => field.name === "source_id")) {
        await vectors.addColumns([{ name: "source_id", valueSql: "''" }]);
      }

      let lastDocumentId: string | undefined;
      while (true) {
        const filters = ["source_id = ''"];
        if (lastDocumentId) filters.push(`document_id > ${sqlString(lastDocumentId)}`);
        const rows = await vectors.query()
          .where(filters.join(" AND "))
          .orderBy({ columnName: "document_id", ascending: true })
          .limit(500)
          .toArray();
        if (rows.length === 0) break;

        const documentIds = rows.map((row) => String((row as Record<string, unknown>).document_id));
        const sourceIds = new Map((await documents.query()
          .where(inFilter("document_id", documentIds))
          .limit(documentIds.length)
          .toArray()).map((row) => {
          const record = row as Record<string, unknown>;
          return [String(record.document_id), String(record.source_id)] as const;
        }));
        const migrated = rows.flatMap((row) => {
          const record = row as Record<string, unknown>;
          const sourceId = sourceIds.get(String(record.document_id));
          const vector = record.vector as Iterable<number> | undefined;
          return sourceId && vector ? [{
            document_id: String(record.document_id),
            collection_id: String(record.collection_id),
            source_id: sourceId,
            content_hash: String(record.content_hash),
            vector: Array.from(vector, Number),
          }] : [];
        });
        if (migrated.length > 0) {
          await vectors.mergeInsert("document_id")
            .whenMatchedUpdateAll()
            .execute(migrated);
        }
        const orphanIds = documentIds.filter((documentId) => !sourceIds.has(documentId));
        if (orphanIds.length > 0) await vectors.delete(inFilter("document_id", orphanIds));
        lastDocumentId = documentIds.at(-1);
        if (rows.length < 500) break;
      }
      if (!(await vectors.listIndices()).some((index) => index.name === "source_id_idx")) {
        await vectors.createIndex("source_id", {
          config: lancedb.Index.btree(),
        });
      }
    }
  }

  private async documentsTable(): Promise<Table> {
    await this.initialize();
    return this.connection!.openTable(DOCUMENT_TABLE);
  }

  private async openVectorTable(embeddingSpaceId: string): Promise<Table | null> {
    await this.initialize();
    const name = vectorTableName(embeddingSpaceId);
    return (await this.connection!.tableNames()).includes(name)
      ? this.connection!.openTable(name)
      : null;
  }

  private async vectorTable(
    embeddingSpaceId: string,
    initialRows: Array<Record<string, unknown>>,
  ): Promise<Table> {
    const existing = await this.openVectorTable(embeddingSpaceId);
    if (existing) return existing;
    if (initialRows.length === 0) throw new Error("Cannot create a vector table without vectors.");
    return this.connection!.createTable(vectorTableName(embeddingSpaceId), initialRows);
  }

  private async ensureVectorIndex(table: Table): Promise<void> {
    if (await table.countRows() < VECTOR_INDEX_THRESHOLD) return;
    if ((await table.listIndices()).some((index) => index.name === "vector_idx")) return;
    await table.createIndex("vector", {
      config: lancedb.Index.hnswSq({ distanceType: "cosine" }),
    });
  }

  private async deleteVectors(documentIds: string[]): Promise<void> {
    if (documentIds.length === 0) return;
    const manifest = await this.readManifest();
    for (const spaceId of new Set(manifest.collections.map((collection) => collection.embeddingSpaceId))) {
      const table = await this.openVectorTable(spaceId);
      if (table) await table.delete(inFilter("document_id", documentIds));
    }
  }

  private async readManifest(): Promise<Manifest> {
    try {
      const parsed = JSON.parse(await readFile(this.manifestPath, "utf8")) as Partial<Manifest>;
      if (parsed.formatVersion !== 1 || !Array.isArray(parsed.collections)) throw new Error("Invalid retrieval manifest.");
      return {
        formatVersion: 1,
        collections: parsed.collections.map((collection) => retrievalCollectionSchema.parse(collection)),
      };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return { formatVersion: 1, collections: [] };
      throw error;
    }
  }

  private async writeManifest(manifest: Manifest): Promise<void> {
    const temporaryPath = `${this.manifestPath}.${process.pid}.${randomUUID()}.tmp`;
    await writeFile(temporaryPath, JSON.stringify(manifest, null, 2), "utf8");
    await rename(temporaryPath, this.manifestPath);
  }

  private serialize<T>(operation: () => Promise<T>): Promise<T> {
    const result = this.writeChain.then(operation, operation);
    this.writeChain = result.catch(() => undefined);
    return result;
  }
}
