import type { RecallFlagAssignment, RecallFlagRule, RetrievalDocument, RetrievalSourceWeight } from "./domain";

export function enhancedRecallScore(
  raw: number,
  document: Pick<RetrievalDocument, "collectionId" | "sourceId">,
  sources: RetrievalSourceWeight[] = [],
  flags: RecallFlagRule[] = [],
  assignments: RecallFlagAssignment[] = [],
): number {
  return recallScoreDetails(raw, document, sources, flags, assignments).score;
}

export function recallScoreDetails(
  raw: number,
  document: Pick<RetrievalDocument, "collectionId" | "sourceId">,
  sources: RetrievalSourceWeight[] = [],
  flags: RecallFlagRule[] = [],
  assignments: RecallFlagAssignment[] = [],
) {
  const source = sources.find((item) => item.collectionId === document.collectionId);
  let additive = source?.addWeight ?? 0;
  let multiplier = source?.weight || 1;
  const ids = new Set(assignments.find((item) => item.collectionId === document.collectionId
    && item.sourceId === document.sourceId)?.flags ?? []);
  for (const flag of flags) {
    if (!ids.has(flag.id)) continue;
    additive += flag.addWeight;
    multiplier *= flag.multiplyWeight || 1;
  }
  const score = (raw + additive) * multiplier;
  return {
    score,
    steps: [
      { label: "source", before: raw, add: source?.addWeight ?? 0, multiply: source?.weight || 1,
        after: (raw + (source?.addWeight ?? 0)) * (source?.weight || 1) },
      ...flags.filter((flag) => ids.has(flag.id)).map((flag) => ({
        label: flag.name, before: raw, add: flag.addWeight, multiply: flag.multiplyWeight || 1,
        after: (raw + flag.addWeight) * (flag.multiplyWeight || 1),
      })),
      { label: "combined", before: raw, add: additive, multiply: multiplier, after: score },
    ],
  };
}
