import { businessRegex, type BusinessRegexSettings } from "../../shared/business-regex";

const MAX_RESPONSE_CHARACTERS = 16 * 1024 * 1024;
const MAX_DEPTH = 256;
const MAX_CANDIDATES = 256;
const MAX_REPAIRS = 16;

class ParseBudget {
  private remaining: number;
  constructor(length: number) { this.remaining = Math.max(65_536, length * 12); }
  spend(amount = 1): void {
    this.remaining -= amount;
    if (this.remaining < 0) throw new Error("模型响应 JSON 解析超过扫描预算。");
  }
}

/** Default tags are scanned once; an unclosed block extends to the end. */
function withoutReasoning(value: string, rules: BusinessRegexSettings): string {
  if (Object.hasOwn(rules, "reasoningClosed") || Object.hasOwn(rules, "reasoningOpen")) {
    const closed = value.replace(businessRegex("reasoningClosed", rules), " ");
    const unclosed = closed.search(businessRegex("reasoningOpen", rules));
    return unclosed < 0 ? closed : closed.slice(0, unclosed);
  }
  const chunks: string[] = [];
  let after = 0;
  let open: string | undefined;
  for (const match of value.matchAll(/<(\/?)(thinking|think)>/gi)) {
    const name = match[2]!.toLowerCase();
    if (!open && !match[1]) {
      chunks.push(value.slice(after, match.index));
      open = name;
    } else if (open === name && match[1]) {
      chunks.push(" ");
      after = match.index + match[0].length;
      open = undefined;
    }
  }
  if (!open) chunks.push(value.slice(after));
  return chunks.join("");
}

/** Cache balanced object boundaries in one pass, including nested candidates. */
function objectEnds(text: string, budget: ParseBudget): Map<number, number> {
  const ends = new Map<number, number>();
  const starts: number[] = [];
  let inString = false;
  let escaped = false;
  let depth = 0;
  for (let index = 0; index < text.length; index += 1) {
    budget.spend();
    const char = text[index];
    if (inString) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === "\"") inString = false;
      continue;
    }
    if (char === "\"" && starts.length) inString = true;
    else if (char === "{") {
      starts.push(index);
      if (++depth > MAX_DEPTH) throw new Error("模型响应 JSON 嵌套超过 256 层。");
    } else if (char === "[") {
      if (starts.length && ++depth > MAX_DEPTH) throw new Error("模型响应 JSON 嵌套超过 256 层。");
    } else if (char === "]") depth = Math.max(0, depth - 1);
    else if (char === "}") {
      const start = starts.pop();
      if (start !== undefined) ends.set(start, index + 1);
      depth = starts.length ? Math.max(0, depth - 1) : 0;
    }
  }
  return ends;
}

/** Repair known quote/whitespace/extra-brace defects, never close truncations. */
function lenientObject(text: string, start: number, budget: ParseBudget): { text: string; end: number } | undefined {
  const open: string[] = [];
  let inString = false;
  let escaped = false;
  let rewritten = "";
  for (let index = start; index < text.length; index += 1) {
    budget.spend();
    const char = text[index];
    let emitted = char;
    if (inString) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === "\"") {
        let next = index + 1;
        while (next < text.length && /\s/.test(text.charAt(next))) { budget.spend(); next += 1; }
        if (next === text.length || ",}]:".includes(text.charAt(next))) inString = false;
        else emitted = "\\\"";
      } else if (char === "\n") emitted = "\\n";
      else if (char === "\r") emitted = "\\r";
      else if (char === "\t") emitted = "\\t";
    } else if (char === "\"") inString = true;
    else if (char === "{" || char === "[") {
      open.push(char);
      if (open.length > MAX_DEPTH) throw new Error("模型响应 JSON 嵌套超过 256 层。");
    } else if (char === "]") open.pop();
    else if (char === "}") {
      if (open.at(-1) === "[") continue;
      open.pop();
      if (!open.length) return { text: rewritten + char, end: index + 1 };
    }
    rewritten += emitted;
  }
  return undefined;
}

function isObject(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

/** Last complete protocol object wins; all recovery and diagnostics share a budget. */
export function parseProviderJsonObject(raw: string, label: string, requiredKey?: string, rules: BusinessRegexSettings = {}): Record<string, unknown> {
  if (raw.length > MAX_RESPONSE_CHARACTERS) throw new Error("模型响应超过 JSON 解析长度限制（16 Mi 字符）。");
  const cleaned = withoutReasoning(raw, rules);
  const budget = new ParseBudget(cleaned.length);
  const ends = objectEnds(cleaned, budget);
  let start = cleaned.indexOf("{");
  let attempts = 0;
  let repairs = 0;
  let found = 0;
  let value: Record<string, unknown> | undefined;
  let diagnostic = "";
  const parse = (span: string): Record<string, unknown> | undefined => {
    budget.spend(span.length * 2);
    try {
      const candidate: unknown = JSON.parse(span);
      return isObject(candidate) ? candidate : undefined;
    } catch (error) {
      if (!diagnostic && requiredKey && span.includes(`"${requiredKey}"`)) {
        const message = (error as SyntaxError).message.slice(0, 300);
        const position = message.match(/\bposition (\d+)/);
        const offset = position ? Number(position[1]) : 0;
        const excerpt = span.slice(Math.max(0, offset - 30), offset + 30);
        diagnostic = ` JSON 解析失败：${message}；${position ? "错误位置附近" : "对象开头"}：${JSON.stringify(excerpt)}`;
      }
      return undefined;
    }
  };
  while (start >= 0) {
    if (++attempts > MAX_CANDIDATES) throw new Error("模型响应 JSON 候选对象超过 256 个。");
    let end = ends.get(start);
    let candidate = end === undefined ? undefined : parse(cleaned.slice(start, end));
    if (!candidate) {
      if (++repairs > MAX_REPAIRS) throw new Error("模型响应 JSON 修复次数超过 16 次。");
      const repaired = lenientObject(cleaned, start, budget);
      if (repaired) { candidate = parse(repaired.text); if (candidate) end = repaired.end; }
    }
    if (candidate) {
      found += 1;
      if (!requiredKey || Object.hasOwn(candidate, requiredKey)) value = candidate;
      start = cleaned.indexOf("{", end);
    } else start = cleaned.indexOf("{", start + 1);
  }
  if (value) return value;
  const message = found && requiredKey
    ? `${label}响应中的 JSON 对象都缺少 "${requiredKey}" 字段；回复可能被截断或格式不符。`
    : `${label}响应中没有找到完整的 JSON 对象；回复可能被截断或不含 JSON。`;
  throw new Error(`${message} 回复长度：${raw.length} 字符；回复末尾（最多 200 字符）：${raw.slice(-200).replace(/\s+/g, " ").trim()}${diagnostic}`);
}
