function redact(value: string, secrets: string[]): string {
  for (const secret of secrets.filter(Boolean)) value = value.replaceAll(secret, "[REDACTED]");
  return value
    .replace(/Bearer\s+[^\s"'<>]+/gi, "Bearer [REDACTED]")
    .replace(/sk-[a-zA-Z0-9_-]+/g, "[REDACTED]")
    .replace(/((?:api[_-]?key|authorization|password|secret|access[_-]?token)["']?\s*[:=]\s*)(?:"[^"]*"|'[^']*'|[^\s,;<>]+)/gi, "$1[REDACTED]");
}

export function providerHttpErrorMessage(status: number, raw: string, secrets: string[] = [], requestId?: string | null): string {
  let detail = "";
  try {
    const payload = JSON.parse(raw);
    const source = typeof payload?.error === "object" && payload.error !== null ? payload.error : payload;
    const fields = [typeof payload?.error === "string" ? payload.error : source?.message,
      source?.code, source?.type, source?.param, source?.path, payload?.request_id ?? payload?.requestId];
    detail = fields.flatMap((value) => typeof value === "string" || typeof value === "number"
      ? [String(value)] : Array.isArray(value) ? [value.join(".")] : []).join(" · ");
  } catch {
    detail = raw.replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim();
  }
  if (requestId) detail += `${detail ? " · " : ""}request_id=${requestId}`;
  detail = redact(detail, secrets).replace(/[\u0000-\u001f\u007f]/g, " ").slice(0, 1500);
  return `Provider returned HTTP ${status}${detail ? `: ${detail}` : "."}`;
}
