import { TaskBudgetExceededError } from "../jobs/task-budget";
import type {
  FailoverDecisionRequired,
  FailoverPolicy,
  GenerationWorkflow,
  ProviderAttempt,
} from "../../shared/domain";

interface EndpointLike {
  id: string;
  name: string;
  enabled: boolean;
  order: number;
}

export class RetrievalProviderError extends Error {
  constructor(
    message: string,
    readonly options: {
      ambiguous: boolean;
      status?: number | undefined;
      code?: string | undefined;
    },
  ) {
    super(message);
    this.name = "RetrievalProviderError";
  }
}

interface HealthRecord {
  definitiveFailures: number;
  openUntil: number;
}

export class EndpointHealthRegistry {
  private readonly records = new Map<string, HealthRecord>();

  constructor(
    private readonly failureThreshold = 3,
    private readonly cooldownMs = 60_000,
  ) {}

  isOpen(endpointId: string, now = Date.now()): boolean {
    return (this.records.get(endpointId)?.openUntil ?? 0) > now;
  }

  succeed(endpointId: string): void {
    this.records.delete(endpointId);
  }

  fail(endpointId: string, now = Date.now()): void {
    const previous = this.records.get(endpointId) ?? { definitiveFailures: 0, openUntil: 0 };
    const definitiveFailures = previous.definitiveFailures + 1;
    this.records.set(endpointId, {
      definitiveFailures,
      openUntil: definitiveFailures >= this.failureThreshold ? now + this.cooldownMs : 0,
    });
  }
}

export interface EndpointChainResult<T> {
  state: "succeeded" | "failed" | "ambiguous";
  value?: T | undefined;
  attempts: ProviderAttempt[];
  decisionRequired?: FailoverDecisionRequired | undefined;
  message?: string | undefined;
}

function orderedEndpoints<TEndpoint extends EndpointLike>(
  endpoints: TEndpoint[],
  resumeAfterEndpointId?: string,
): TEndpoint[] {
  const ordered = [...endpoints]
    .sort((left, right) => left.order - right.order || left.id.localeCompare(right.id));
  if (!resumeAfterEndpointId) return ordered.filter((endpoint) => endpoint.enabled);
  const position = ordered.findIndex((endpoint) => endpoint.id === resumeAfterEndpointId);
  if (position < 0) return [];
  return ordered.slice(position + 1).filter((endpoint) => endpoint.enabled);
}

function providerError(error: unknown): RetrievalProviderError {
  if (error instanceof RetrievalProviderError) return error;
  return new RetrievalProviderError(
    error instanceof Error ? error.message : String(error),
    { ambiguous: false },
  );
}

export async function runEndpointChain<TValue, TEndpoint extends EndpointLike>(options: {
  provider: "generation" | "embedding" | "rerank";
  workflow?: GenerationWorkflow | undefined;
  endpoints: TEndpoint[];
  policy: FailoverPolicy;
  resumeAfterEndpointId?: string | undefined;
  health?: EndpointHealthRegistry | undefined;
  signal?: AbortSignal | undefined;
  resolveEndpoint?: ((endpoint: TEndpoint) => Promise<TEndpoint>) | undefined;
  invoke: (endpoint: TEndpoint) => Promise<TValue>;
}): Promise<EndpointChainResult<TValue>> {
  const endpoints = orderedEndpoints(options.endpoints, options.resumeAfterEndpointId);
  const attempts: ProviderAttempt[] = [];
  if (endpoints.length === 0) {
    return { state: "failed", attempts, message: "No enabled provider endpoint is available." };
  }

  for (const [index, endpoint] of endpoints.entries()) {
    if (options.signal?.aborted) throw options.signal.reason ?? new Error("Cancelled.");
    if (options.health?.isOpen(endpoint.id)) {
      attempts.push({
        endpointId: endpoint.id,
        endpointName: endpoint.name,
        outcome: "skipped",
        durationMs: 0,
        message: "Circuit breaker is open.",
      });
      continue;
    }

    const startedAt = Date.now();
    try {
      const runtimeEndpoint = options.resolveEndpoint
        ? await options.resolveEndpoint(endpoint)
        : endpoint;
      const value = await options.invoke(runtimeEndpoint);
      options.health?.succeed(endpoint.id);
      attempts.push({
        endpointId: endpoint.id,
        endpointName: endpoint.name,
        outcome: "succeeded",
        durationMs: Date.now() - startedAt,
      });
      return { state: "succeeded", value, attempts };
    } catch (rawError) {
      if (options.signal?.aborted) throw options.signal.reason ?? rawError;
      if (rawError instanceof TaskBudgetExceededError) throw rawError;
      const error = providerError(rawError);
      const ambiguous = error.options.ambiguous;
      attempts.push({
        endpointId: endpoint.id,
        endpointName: endpoint.name,
        outcome: ambiguous ? "ambiguous_failure" : "definitive_failure",
        durationMs: Date.now() - startedAt,
        ...(error.options.status ? { status: error.options.status } : {}),
        message: error.message,
      });
      if (!ambiguous) {
        options.health?.fail(endpoint.id);
        continue;
      }

      if (options.policy === "always") continue;
      const nextEndpoint = endpoints[index + 1];
      if (options.policy === "confirm_ambiguous") {
        return {
          state: "ambiguous",
          attempts,
          message: error.message,
          decisionRequired: {
            kind: "ambiguous_failover",
            provider: options.provider,
            ...(options.workflow ? { workflow: options.workflow } : {}),
            failedEndpointId: endpoint.id,
            ...(nextEndpoint ? { nextEndpointId: nextEndpoint.id } : {}),
            message: "The provider may have completed and billed this request. Continue with the next endpoint only after confirmation.",
          },
        };
      }
      return { state: "ambiguous", attempts, message: error.message };
    }
  }

  const last = attempts.at(-1);
  return {
    state: last?.outcome === "ambiguous_failure" ? "ambiguous" : "failed",
    attempts,
    message: last?.message ?? "All enabled provider endpoints failed.",
  };
}
