import type {
  EndpointModelListRequest,
  EndpointModelListResult,
  EndpointTestResult,
  FailoverPolicy,
  GenerationEndpoint,
  GenerationEndpointGroup,
  GenerationWorkflow,
  PromptMessageInput,
  RetrievalEndpoint,
} from "../../shared/domain";
import type { JobContext } from "../jobs/job-manager";
import type { DiscussionEvent, DiscussionMessage, DiscussionRequest, DiscussionResult } from "../../shared/discussion";
import { requestModelCatalog, requestStructuredCompletion } from "../providers/openai-compatible";
import { parseConfiguredProviderJson } from "./business-regex";
import {
  EndpointHealthRegistry,
  runEndpointChain,
  type EndpointChainResult,
} from "../retrieval/endpoint-failover";

export class GenerationService {
  private readonly health = new EndpointHealthRegistry();

  constructor(
    private readonly resolveEndpoint: <T extends GenerationEndpoint | RetrievalEndpoint>(endpoint: T) => Promise<T> =
      async (endpoint) => structuredClone(endpoint),
  ) {}

  run(options: {
    workflow: GenerationWorkflow;
    group: GenerationEndpointGroup;
    policy: FailoverPolicy;
    resumeAfterEndpointId?: string | undefined;
    messages: PromptMessageInput[] | DiscussionMessage[];
    context: JobContext;
    onDiscussionEvent?: ((event: DiscussionEvent) => void) | undefined;
  }): Promise<EndpointChainResult<string>> {
    return runEndpointChain({
      provider: "generation",
      workflow: options.workflow,
      endpoints: options.group.endpoints,
      policy: options.policy,
      resumeAfterEndpointId: options.resumeAfterEndpointId,
      health: this.health,
      signal: options.context.signal,
      resolveEndpoint: this.resolveEndpoint,
      invoke: (endpoint) => {
        options.onDiscussionEvent?.({ type: "endpoint", name: endpoint.name, streaming: endpoint.streaming });
        return requestStructuredCompletion({
          config: options.workflow === "discussion" ? { ...endpoint, jsonMode: false } : endpoint,
          messages: options.messages,
          signal: options.context.signal,
          onProgress: (characters) => options.context.report(
            Math.min(0.75, 0.1 + characters / 100_000),
            `Receiving model output (${characters} chars)`,
          ),
          onDelta: options.onDiscussionEvent
            ? (text) => options.onDiscussionEvent!({ type: "delta", text })
            : undefined,
        });
      },
    });
  }

  async discuss(
    request: DiscussionRequest,
    context: JobContext,
    onEvent: (event: DiscussionEvent) => void,
  ): Promise<DiscussionResult> {
    const result = await this.run({
      workflow: "discussion", group: request.generationGroup,
      policy: request.failoverPolicy, resumeAfterEndpointId: request.resumeAfterEndpointId,
      messages: request.messages, context, onDiscussionEvent: onEvent,
    });
    if (result.state === "succeeded") {
      return { outcome: "completed", text: result.value!, attempts: result.attempts };
    }
    if (result.decisionRequired) {
      return { outcome: "decision_required", attempts: result.attempts,
        decisionRequired: result.decisionRequired, message: result.message };
    }
    throw Object.assign(new Error(result.message ?? "剧情讨论生成失败。"), {
      code: result.state === "ambiguous" ? "AMBIGUOUS_PROVIDER_OUTCOME" : "DISCUSSION_FAILED",
    });
  }

  async listModels(input: EndpointModelListRequest, context: JobContext): Promise<EndpointModelListResult> {
    const endpoint: RetrievalEndpoint = {
      id: "model_catalog",
      name: "Model catalog",
      baseUrl: input.baseUrl,
      allowPrivateNetwork: input.allowPrivateNetwork === true,
      ...(input.credentialId ? { credentialId: input.credentialId } : {}),
      ...(input.apiKey ? { apiKey: input.apiKey } : {}),
      model: "model-catalog",
      timeoutMs: input.timeoutMs,
      enabled: true,
      order: 0,
    };
    const runtimeEndpoint = await this.resolveEndpoint(endpoint);
    const startedAt = Date.now();
    context.report(0.2, "Requesting provider model catalog");
    const models = await requestModelCatalog({ config: runtimeEndpoint, signal: context.signal });
    context.report(1, `Loaded ${models.length} models`);
    return { models, latencyMs: Date.now() - startedAt };
  }

  async testEndpoint(endpoint: GenerationEndpoint, context: JobContext): Promise<EndpointTestResult> {
    const startedAt = Date.now();
    let stage = "连接端点";
    context.report(0.1, "按端点配置测试连接");
    const result = await runEndpointChain({
      provider: "generation",
      workflow: "summary",
      endpoints: [{ ...endpoint, enabled: true, order: 0 }],
      policy: "definitive_only",
      health: this.health,
      signal: context.signal,
      resolveEndpoint: this.resolveEndpoint,
      invoke: (candidate) => requestStructuredCompletion({
        config: candidate,
        messages: [
          { role: "system", content: "Return a JSON object only." },
          { role: "user", content: "Return {\"ok\":true}." },
        ],
        signal: context.signal,
        onResponse: () => {
          stage = "读取响应";
          context.report(0.4, "端点已响应，正在读取模型输出");
        },
        onProgress: (characters) => context.report(0.6, `正在读取模型输出（${characters} 字符）`),
      }),
    });
    if (result.state !== "succeeded") {
      throw Object.assign(new Error(`${stage}失败：${result.message ?? "Generation endpoint test failed."}`), {
        statusCode: 502,
        code: result.state === "ambiguous" ? "AMBIGUOUS_PROVIDER_OUTCOME" : "ENDPOINT_TEST_FAILED",
      });
    }
    context.report(0.9, "响应读取完成，正在解析测试结果");
    try { await parseConfiguredProviderJson(result.value ?? "", "端点测试", undefined, {}, context.signal); }
    catch (error) {
      throw Object.assign(new Error(`端点连接与响应读取成功，但输出解析失败：${error instanceof Error ? error.message : String(error)}`), {
        statusCode: 502, code: "INVALID_ENDPOINT_TEST_RESPONSE",
      });
    }
    return {
      endpointId: endpoint.id,
      kind: "generation",
      latencyMs: Date.now() - startedAt,
      attempts: result.attempts,
    };
  }
}
