import { request as httpRequest, type IncomingHttpHeaders, type RequestOptions } from "node:http";
import { request as httpsRequest } from "node:https";
import { isIP } from "node:net";
import { Readable } from "node:stream";
import { activeTaskBudget } from "../jobs/task-budget";

import {
  resolveProviderTarget,
  type ValidatedProviderTarget,
} from "./provider-url";

export const MAX_PROVIDER_RESPONSE_BYTES = 16 * 1024 * 1024;
export const MAX_PROVIDER_ERROR_BYTES = 64 * 1024;

export class ProviderResponseTooLargeError extends Error {
  constructor(readonly limit: number) {
    super(`Provider response exceeded the ${limit}-byte safety limit.`);
    this.name = "ProviderResponseTooLargeError";
  }
}

/** Node network error code from the error itself or its cause. */
export function networkErrorCode(error: unknown): string {
  const direct = (error as { code?: unknown })?.code;
  if (typeof direct === "string") return direct;
  const cause = (error as { cause?: { code?: unknown } })?.cause;
  return typeof cause?.code === "string" ? cause.code : "";
}

function responseHeaders(raw: IncomingHttpHeaders): Headers {
  const headers = new Headers();
  for (const [name, value] of Object.entries(raw)) {
    if (Array.isArray(value)) {
      for (const item of value) headers.append(name, item);
    } else if (value !== undefined) {
      headers.set(name, value);
    }
  }
  return headers;
}

function pinnedRequest(
  target: ValidatedProviderTarget,
  options: {
    method: "GET" | "POST";
    headers: Record<string, string>;
    body?: string | undefined;
    signal: AbortSignal;
  },
): Promise<Response> {
  return new Promise((resolve, reject) => {
    if (options.signal.aborted) {
      reject(options.signal.reason ?? new Error("Provider request was cancelled."));
      return;
    }
    const address = target.addresses[0];
    if (!address) {
      reject(new Error("Provider host resolved to an empty address set."));
      return;
    }
    const requestOptions: RequestOptions = {
      protocol: target.url.protocol,
      hostname: target.url.hostname.replace(/^\[|\]$/g, ""),
      port: target.url.port || undefined,
      path: `${target.url.pathname}${target.url.search}`,
      method: options.method,
      headers: options.headers,
      lookup: (_hostname, lookupOptions, callback) => {
        const family = isIP(address);
        if (typeof lookupOptions === "object" && lookupOptions.all) {
          callback(null, [{ address, family }]);
        } else {
          callback(null, address, family);
        }
      },
    };
    const request = (target.url.protocol === "https:" ? httpsRequest : httpRequest)(
      requestOptions,
      (incoming) => {
        const status = incoming.statusCode ?? 500;
        const noBody = status === 204 || status === 205 || status === 304;
        const body = noBody
          ? null
          : Readable.toWeb(incoming) as ReadableStream<Uint8Array>;
        resolve(new Response(body, {
          status,
          ...(incoming.statusMessage ? { statusText: incoming.statusMessage } : {}),
          headers: responseHeaders(incoming.headers),
        }));
        incoming.once("close", () => {
          options.signal.removeEventListener("abort", abort);
        });
      },
    );
    const abort = () => request.destroy(
      options.signal.reason instanceof Error
        ? options.signal.reason
        : new Error("Provider request was cancelled."),
    );
    options.signal.addEventListener("abort", abort, { once: true });
    request.once("error", (error) => {
      options.signal.removeEventListener("abort", abort);
      reject(error);
    });
    request.end(options.body);
  });
}

export async function requestProvider(
  rawUrl: string,
  options: {
    method: "GET" | "POST";
    headers: Record<string, string>;
    body?: string | undefined;
    signal: AbortSignal;
  },
  securityOptions: Parameters<typeof resolveProviderTarget>[1] = {},
): Promise<Response> {
  const target = await resolveProviderTarget(rawUrl, securityOptions);
  activeTaskBudget.getStore()?.reserve(options.body);
  return pinnedRequest(target, options);
}

export async function readResponseTextLimited(
  response: Response,
  limit = MAX_PROVIDER_RESPONSE_BYTES,
): Promise<string> {
  if (!response.body) return "";
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let received = 0;
  let text = "";
  while (true) {
    const { value, done } = await reader.read();
    if (value) {
      received += value.byteLength;
      if (received > limit) {
        await reader.cancel().catch(() => undefined);
        throw new ProviderResponseTooLargeError(limit);
      }
      text += decoder.decode(value, { stream: !done });
    }
    if (done) break;
  }
  text += decoder.decode();
  return text;
}
