import { z } from "zod";
import type { FailoverDecisionRequired, GenerationEndpointGroup, ProviderAttempt } from "./domain";
import { failoverPolicySchema, generationEndpointGroupSchema, identifierSchema } from "./schemas";

export const DEFAULT_DISCUSSION_SYSTEM_PROMPT = `现在暂停剧情演绎，进入剧情讨论模式。以中文与用户讨论创作，而不是继续扮演人物或推进故事。
前面的角色资料、世界设定、记忆与聊天是讨论背景。用户通常是主持人，扮演世界与其他人物，不应默认把用户当作世界内名叫“User”的人物。
区分已经发生的事实、角色目前的认知、尚未揭露的设定与可以选择的创作方案；没有依据时明确说明未知，不要把猜测写成既定事实，也不要让角色自动获得背景中的全部知识。
围绕用户本次提出的问题作答，可以分析人物动机、情感与关系、因果、伏笔、节奏、设定一致性及后续发展的不同可能。讨论中的提议不代表剧情已发生或用户已采纳，不要更新记忆、状态或代替用户决定剧情。`;

export const discussionSettingsSchema = z.object({
  systemPrompt: z.string().trim().min(1).max(100_000).default(DEFAULT_DISCUSSION_SYSTEM_PROMPT),
  presets: z.array(z.object({
    id: identifierSchema,
    name: z.string().trim().min(1).max(200),
    content: z.string().trim().min(1).max(100_000),
  }).strict()).max(200).default([]),
}).strict().refine((value) => new Set(value.presets.map((preset) => preset.id)).size === value.presets.length,
  "剧情讨论预设 ID 不能重复。");

export type DiscussionSettings = z.infer<typeof discussionSettingsSchema>;

// Preserve the native multimodal and tool-history fields; never flatten them into text.
export const discussionMessageSchema = z.object({
  role: z.enum(["system", "developer", "user", "assistant", "tool", "function"]),
  content: z.union([z.string(), z.array(z.unknown()), z.null()]).optional(),
}).passthrough();
export type DiscussionMessage = z.infer<typeof discussionMessageSchema>;

export const discussionRequestSchema = z.object({
  chatId: z.string().min(1).max(1000),
  messages: z.array(discussionMessageSchema).min(3).max(20_000),
  generationGroup: generationEndpointGroupSchema,
  failoverPolicy: failoverPolicySchema,
  resumeAfterEndpointId: identifierSchema.optional(),
}).strict();
export type DiscussionRequest = Omit<z.infer<typeof discussionRequestSchema>, "generationGroup"> & {
  generationGroup: GenerationEndpointGroup;
};

export interface DiscussionResult {
  outcome: "completed" | "decision_required";
  text?: string | undefined;
  attempts: ProviderAttempt[];
  decisionRequired?: FailoverDecisionRequired | undefined;
  message?: string | undefined;
}

export type DiscussionEvent =
  | { type: "job"; jobId: string }
  | { type: "endpoint"; name: string; streaming: boolean }
  | { type: "delta"; text: string }
  | { type: "result"; result: DiscussionResult }
  | { type: "error"; message: string; cancelled?: boolean }
  | { type: "heartbeat" };
