import type { ChatMessageInput, SummaryBatchingConfig, SummarySliceCandidate } from "../../shared/domain";

export const DEFAULT_SUMMARY_BATCHING: SummaryBatchingConfig = {
  enabled: true, maxCharacters: 60000, overlapCharacters: 1000, maxSubBatches: 8,
};

export interface SummaryPart {
  messages: ChatMessageInput[];
  overlap: string;
  ranges: Array<{ messageId: string; start: number; end: number }>;
}

export function splitSummaryMessages(messages: ChatMessageInput[], config = DEFAULT_SUMMARY_BATCHING): SummaryPart[] {
  if (!messages.length) throw new Error("没有可总结内容。");
  const total = messages.reduce((sum, message) => sum + message.content.length, 0);
  const maximum = config.enabled ? config.maxCharacters : Number.POSITIVE_INFINITY;
  if (messages.length <= 500 && total <= maximum) return [{
    messages: structuredClone(messages), overlap: "",
    ranges: messages.map((message) => ({ messageId: message.id, start: 0, end: message.content.length })),
  }];
  if (Math.max(Math.ceil(total / maximum), Math.ceil(messages.length / 500)) > config.maxSubBatches) {
    throw new Error(`当前范围需要超过 ${config.maxSubBatches} 个子请求。请缩小楼层范围或调整子批次预算；尚未调用模型。`);
  }
  const parts: SummaryPart[] = [];
  let part: SummaryPart = { messages: [], overlap: "", ranges: [] };
  let characters = 0;
  let tail = "";
  const finish = () => {
    if (!part.messages.length) return;
    parts.push(part);
    tail = config.enabled && config.overlapCharacters
      ? (tail + part.messages.map((message) => message.content).join("\n")).slice(-config.overlapCharacters) : "";
    if (/^[\uDC00-\uDFFF]/.test(tail)) tail = tail.slice(1);
    part = { messages: [], overlap: config.overlapCharacters ? tail : "", ranges: [] };
    characters = 0;
  };
  for (const message of messages) {
    for (let start = 0; start < message.content.length;) {
      // Reserve one context slot for overlap as well as enforcing the target-message cap.
      if (part.messages.length >= (part.overlap ? 499 : 500)) finish();
      let end = Math.min(message.content.length, start + maximum - characters);
      // Keep UTF-16 surrogate pairs intact without interpreting narrative formatting.
      if (end < message.content.length && /[\uD800-\uDBFF]/.test(message.content[end - 1]!)) end--;
      if (end === start) { finish(); continue; }
      const content = message.content.slice(start, end);
      part.messages.push({ ...message, content });
      part.ranges.push({ messageId: message.id, start, end });
      characters += content.length;
      start = end;
      if (characters >= maximum - 1) finish();
    }
  }
  finish();
  if (parts.length > config.maxSubBatches) throw new Error("子批次数超过预算，尚未调用模型。");
  return parts;
}

export function summaryPropositionKey(slice: Pick<SummarySliceCandidate, "timestamp" | "content" | "continuity">): string {
  return `${slice.timestamp}\0${slice.content.normalize("NFKC").replace(/\s+/g, " ").trim()}\0${JSON.stringify(slice.continuity ?? {})}`;
}

export function mergeSummaryCandidates(candidates: SummarySliceCandidate[]): SummarySliceCandidate[] {
  const merged = new Map<string, SummarySliceCandidate>();
  for (const candidate of candidates) {
    const key = summaryPropositionKey(candidate);
    const old = merged.get(key);
    if (old) old.tags = [...new Set([...old.tags, ...candidate.tags])].slice(0, 100);
    else merged.set(key, structuredClone(candidate));
  }
  return [...merged.values()];
}
