import { AsyncLocalStorage } from "node:async_hooks";
import type { TaskBudgetConfig, TaskUsage } from "../../shared/domain";

export const requestBudget = new AsyncLocalStorage<TaskBudgetConfig>();
export const activeTaskBudget = new AsyncLocalStorage<TaskBudget>();

export class TaskBudgetExceededError extends Error {
  readonly code = "TASK_BUDGET_EXCEEDED";
  readonly retryable = false;
}

export class TaskBudget {
  readonly startedAt = Date.now();
  readonly usage: TaskUsage = {
    providerCalls: 0, inputCharacters: 0, estimatedInputTokens: 0,
    inputTokens: 0, outputTokens: 0, cachedInputTokens: 0, reportedCalls: 0,
  };

  constructor(readonly config: TaskBudgetConfig, private readonly changed: (usage: TaskUsage) => void = () => {}) {}

  reserve(body: string = ""): void {
    const nextCharacters = this.usage.inputCharacters + body.length;
    if (this.config.maxProviderCalls > 0 && this.usage.providerCalls >= this.config.maxProviderCalls) {
      throw new TaskBudgetExceededError("已达到本任务供应商调用上限，未提交下一次请求。");
    }
    if (this.config.maxInputCharacters > 0 && nextCharacters > this.config.maxInputCharacters) {
      throw new TaskBudgetExceededError("下一次请求将超过本任务累计请求字符预算，未提交。");
    }
    if (this.config.maxDurationMs > 0 && Date.now() - this.startedAt >= this.config.maxDurationMs) {
      throw new TaskBudgetExceededError("已达到本任务时间预算，未提交下一次请求。");
    }
    this.usage.providerCalls += 1;
    this.usage.inputCharacters = nextCharacters;
    this.usage.estimatedInputTokens += Math.ceil(body.length / 2);
    this.changed({ ...this.usage });
  }

  record(payload: unknown): void {
    if (!payload || typeof payload !== "object") return;
    const usage = (payload as { usage?: Record<string, unknown> }).usage;
    if (!usage || typeof usage !== "object") return;
    const number = (value: unknown) => typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : 0;
    this.usage.inputTokens += number(usage.prompt_tokens ?? usage.input_tokens);
    this.usage.outputTokens += number(usage.completion_tokens ?? usage.output_tokens);
    this.usage.cachedInputTokens += number(((usage.prompt_tokens_details ?? usage.input_tokens_details) as Record<string, unknown> | undefined)?.cached_tokens);
    this.usage.reportedCalls += 1;
    this.changed({ ...this.usage });
  }
}
