import { sha256Hex } from "./crypto-compat";
import type {
  JsonPrimitive,
  JsonValue,
  StatusPatchOperation,
  StatusState,
  StatusValidationConfig,
  StatusValidationRule,
  StatusValidationType,
} from "./domain";

const BLOCKED_SEGMENTS = new Set(["__proto__", "prototype", "constructor"]);

export class StatusValidationError extends Error {
  readonly code = "INVALID_STATUS_UPDATE";

  constructor(message: string) {
    super(message);
    this.name = "StatusValidationError";
  }
}

function isObject(value: JsonValue | undefined): value is Record<string, JsonValue> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function assertPath(path: string[]): void {
  if (path.length === 0) throw new StatusValidationError("Status paths cannot be empty.");
  for (const segment of path) {
    if (!segment || segment.length > 200 || BLOCKED_SEGMENTS.has(segment)) {
      throw new StatusValidationError(`Unsafe status path segment: ${segment || "(empty)"}.`);
    }
  }
}

function assertOperations(
  operations: StatusPatchOperation[],
  evidenceMessageIds: ReadonlySet<string>,
): void {
  for (const [index, operation] of operations.entries()) {
    assertPath(operation.path);
    if (operation.evidenceMessageIds.length === 0
      || operation.evidenceMessageIds.some((id) => !evidenceMessageIds.has(id))) {
      throw new StatusValidationError(`Operation ${index + 1} cites evidence outside this update.`);
    }
  }
}

function setAtPath(root: StatusState, path: string[], value: JsonValue): void {
  let cursor: Record<string, JsonValue> = root;
  for (const segment of path.slice(0, -1)) {
    const existing = cursor[segment];
    if (existing === undefined) {
      const child: Record<string, JsonValue> = {};
      cursor[segment] = child;
      cursor = child;
      continue;
    }
    if (!isObject(existing)) {
      throw new StatusValidationError(`Cannot descend through non-object status path: ${path.join(".")}.`);
    }
    cursor = existing;
  }
  cursor[path.at(-1)!] = structuredClone(value);
}

function deleteAtPath(root: StatusState, path: string[]): void {
  let cursor: Record<string, JsonValue> = root;
  for (const segment of path.slice(0, -1)) {
    const existing = cursor[segment];
    if (!isObject(existing)) return;
    cursor = existing;
  }
  delete cursor[path.at(-1)!];
}

interface MatchedValue {
  path: string[];
  value: JsonValue;
}

interface MatchResult {
  values: MatchedValue[];
  missingPaths: string[][];
}

function matchRule(
  current: JsonValue,
  rulePath: string[],
  index = 0,
  path: string[] = [],
): MatchResult {
  if (index === rulePath.length) return { values: [{ path, value: current }], missingPaths: [] };
  if (!isObject(current)) {
    return { values: [], missingPaths: [[...path, ...rulePath.slice(index)]] };
  }
  const segment = rulePath[index]!;
  if (segment === "*") {
    const entries = Object.entries(current);
    if (entries.length === 0) {
      return { values: [], missingPaths: [[...path, ...rulePath.slice(index)]] };
    }
    return entries.reduce<MatchResult>((result, [key, value]) => {
      const matched = matchRule(value, rulePath, index + 1, [...path, key]);
      result.values.push(...matched.values);
      result.missingPaths.push(...matched.missingPaths);
      return result;
    }, { values: [], missingPaths: [] });
  }
  const next = current[segment];
  return next === undefined
    ? { values: [], missingPaths: [[...path, ...rulePath.slice(index)]] }
    : matchRule(next, rulePath, index + 1, [...path, segment]);
}

function matchValues(current: JsonValue, rulePath: string[]): MatchedValue[] {
  return matchRule(current, rulePath).values;
}

function valueType(value: JsonValue): StatusValidationType {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (typeof value === "object") return "object";
  return typeof value as "string" | "number" | "boolean";
}

function primitiveEquals(left: JsonValue, right: JsonPrimitive): boolean {
  return left === right;
}

function validateRule(
  state: StatusState,
  previousState: StatusState,
  rule: StatusValidationRule,
  changedOnly = false,
): void {
  if (rule.path.length === 0 || rule.path.some((segment) =>
    segment !== "*" && (!segment || segment.length > 200 || BLOCKED_SEGMENTS.has(segment)))) {
    throw new StatusValidationError(`Unsafe validation path: ${rule.path.join(".")}.`);
  }
  const matched = matchRule(state, rule.path);
  const values = matched.values;
  const oldMatches = matchRule(previousState, rule.path);
  const previouslyMissing = new Set(oldMatches.missingPaths.map((path) => path.join("\0")));
  const missingPaths = changedOnly
    ? matched.missingPaths.filter((path) => !previouslyMissing.has(path.join("\0")))
    : matched.missingPaths;
  if (rule.required && (missingPaths.length > 0 || !changedOnly && values.length === 0)) {
    const missingPath = missingPaths[0] ?? rule.path;
    throw new StatusValidationError(`${rule.name} is required at ${missingPath.join(".")}.`);
  }
  const previous = new Map(matchValues(previousState, rule.path).map((item) => [item.path.join("\0"), item.value]));
  for (const item of values) {
    const oldValue = previous.get(item.path.join("\0"));
    if (changedOnly && oldValue !== undefined && canonical(item.value) === canonical(oldValue)) continue;
    if (valueType(item.value) !== rule.type) {
      throw new StatusValidationError(`${rule.name} must be ${rule.type}.`);
    }
    if (rule.enumValues && !rule.enumValues.some((candidate) => primitiveEquals(item.value, candidate))) {
      throw new StatusValidationError(`${rule.name} is outside its allowed values.`);
    }
    if (typeof item.value === "number") {
      if (rule.minimum !== undefined && item.value < rule.minimum) {
        throw new StatusValidationError(`${rule.name} is below its minimum.`);
      }
      if (rule.maximum !== undefined && item.value > rule.maximum) {
        throw new StatusValidationError(`${rule.name} exceeds its maximum.`);
      }
      if (rule.maxDelta !== undefined && typeof oldValue === "number"
        && Math.abs(item.value - oldValue) > rule.maxDelta) {
        throw new StatusValidationError(`${rule.name} exceeds its maximum single-update change.`);
      }
    }
  }
}

function pathCovered(path: string[], rules: StatusValidationRule[]): boolean {
  return rules.some((rule) => {
    if (path.length > rule.path.length && rule.type !== "object") return false;
    return path.slice(0, rule.path.length).every((segment, index) =>
      rule.path[index] === "*" || rule.path[index] === segment);
  });
}

function validateKnownPaths(
  value: StatusState,
  rules: StatusValidationRule[],
  path: string[] = [],
  previous?: StatusState,
): void {
  for (const [key, child] of Object.entries(value)) {
    const childPath = [...path, key];
    const oldValue = previous?.[key];
    if (oldValue !== undefined && canonical(child) === canonical(oldValue)) continue;
    if (!pathCovered(childPath, rules)) {
      throw new StatusValidationError(`Unknown status field: ${childPath.join(".")}.`);
    }
    if (isObject(child)) validateKnownPaths(child, rules, childPath, isObject(oldValue) ? oldValue : undefined);
  }
}

function assertSafeValue(value: JsonValue, path: string[] = []): void {
  if (Array.isArray(value)) {
    value.forEach((item, index) => assertSafeValue(item, [...path, String(index)]));
    return;
  }
  if (!isObject(value)) return;
  for (const [key, child] of Object.entries(value)) {
    if (BLOCKED_SEGMENTS.has(key)) {
      throw new StatusValidationError(`Unsafe status field: ${[...path, key].join(".")}.`);
    }
    assertSafeValue(child, [...path, key]);
  }
}

export function validateStatusState(
  state: StatusState,
  previousState: StatusState,
  validation: StatusValidationConfig,
  changedOnly = false,
): void {
  assertSafeValue(state);
  if (validation.unknownFields === "reject") {
    validateKnownPaths(state, validation.rules, [], changedOnly ? previousState : undefined);
  }
  for (const rule of validation.rules) validateRule(state, previousState, rule, changedOnly);
}

export function applyStatusOperations(options: {
  baseState: StatusState;
  operations: StatusPatchOperation[];
  evidenceMessageIds: Iterable<string>;
  validation: StatusValidationConfig;
}): StatusState {
  assertOperations(options.operations, new Set(options.evidenceMessageIds));
  const next = structuredClone(options.baseState);
  for (const operation of options.operations) {
    if (operation.op === "set") setAtPath(next, operation.path, operation.value);
    else deleteAtPath(next, operation.path);
  }
  // Convert only explicit numeric/boolean strings where the user declared that type.
  for (const rule of options.validation.rules) {
    for (const { path, value } of matchValues(next, rule.path)) {
      if (typeof value !== "string") continue;
      const old = matchValues(options.baseState, path)[0]?.value;
      if (value === old) continue;
      const text = value.trim();
      if (rule.type === "number" && /^[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?$/.test(text)
        && Number.isFinite(Number(text))) setAtPath(next, path, Number(text));
      if (rule.type === "boolean" && /^(true|false)$/i.test(text)) {
        setAtPath(next, path, text.toLowerCase() === "true");
      }
    }
  }
  validateStatusState(next, options.baseState, options.validation, true);
  return next;
}

function canonical(value: JsonValue): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
  return `{${Object.keys(value).sort().map((key) =>
    `${JSON.stringify(key)}:${canonical(value[key]!)}`).join(",")}}`;
}

export function canonicalStatusJson(state: StatusState): string {
  return canonical(state);
}

export async function statusStateHash(state: StatusState): Promise<string> {
  return sha256Hex(canonicalStatusJson(state));
}
