import type { PromptMessageInput, SecondaryApiConfig } from "../../shared/domain";
import type { DiscussionMessage } from "../../shared/discussion";
import { RetrievalProviderError } from "../retrieval/endpoint-failover";
import { combineAbortSignals } from "../security/abort-signal";
import {
  MAX_PROVIDER_RESPONSE_BYTES,
  networkErrorCode,
  ProviderResponseTooLargeError,
  readResponseTextLimited,
  requestProvider,
} from "../security/provider-transport";
import { ProviderUrlPolicyError } from "../security/provider-url";
import { activeTaskBudget, TaskBudgetExceededError } from "../jobs/task-budget";
import { providerHttpErrorMessage } from "./provider-error";

interface ChatCompletionChunk {
  usage?: Record<string, unknown>;
  choices?: Array<{
    delta?: { content?: string };
    message?: { content?: string };
    finish_reason?: string | null;
  }>;
}

export class ProviderCallError extends RetrievalProviderError {
  readonly code: string;

  constructor(
    message: string,
    readonly status: number,
    readonly retryable: boolean,
    ambiguous = false,
  ) {
    super(message, { ambiguous, status, code: status === 200 ? "INVALID_PROVIDER_RESPONSE" : `PROVIDER_HTTP_${status}` });
    this.name = "ProviderCallError";
    this.code = status === 200 ? "INVALID_PROVIDER_RESPONSE" : `PROVIDER_HTTP_${status}`;
  }
}

export function completionUrl(baseUrl: string): string {
  const normalized = baseUrl.replace(/\/+$/, "");
  if (/\/chat\/completions$/i.test(normalized)) return normalized;
  if (/\/v1$/i.test(normalized)) return `${normalized}/chat/completions`;
  return `${normalized}/v1/chat/completions`;
}

export function modelsUrl(baseUrl: string): string {
  const url = new URL(baseUrl);
  let pathname = url.pathname.replace(/\/+$/, "");
  pathname = pathname.replace(/\/(?:chat\/completions|embeddings|rerank)$/i, "");
  if (!/\/v\d+$/i.test(pathname)) pathname = `${pathname}/v1`;
  url.pathname = `${pathname}/models`.replace(/\/{2,}/g, "/");
  url.search = "";
  url.hash = "";
  return url.toString();
}

export function parseModelCatalog(payload: unknown): string[] {
  const source = Array.isArray(payload)
    ? payload
    : Array.isArray((payload as { data?: unknown })?.data)
      ? (payload as { data: unknown[] }).data
      : Array.isArray((payload as { models?: unknown })?.models)
        ? (payload as { models: unknown[] }).models
        : [];
  const models = source.flatMap((item) => {
    if (typeof item === "string") return [item.trim()];
    if (!item || typeof item !== "object") return [];
    const record = item as Record<string, unknown>;
    const value = record.id ?? record.name ?? record.model;
    return typeof value === "string" ? [value.trim()] : [];
  }).filter((model) => model.length > 0 && model.length <= 200);
  const unique = [...new Set(models)].sort((left, right) => left.localeCompare(right));
  if (unique.length === 0) throw new Error("Provider returned no usable model IDs.");
  if (unique.length > 10_000) throw new Error("Provider returned too many models.");
  return unique;
}

export async function requestModelCatalog(options: {
  config: Pick<SecondaryApiConfig, "baseUrl" | "allowPrivateNetwork" | "apiKey" | "timeoutMs">;
  signal: AbortSignal;
}): Promise<string[]> {
  const timeoutController = new AbortController();
  const timeout = setTimeout(() => timeoutController.abort(), options.config.timeoutMs);
  const combined = combineAbortSignals([options.signal, timeoutController.signal]);
  try {
    const response = await requestProvider(modelsUrl(options.config.baseUrl), {
      method: "GET",
      signal: combined.signal,
      headers: {
        Accept: "application/json",
        ...(options.config.apiKey ? { Authorization: `Bearer ${options.config.apiKey}` } : {}),
      },
    }, {
      allowPrivateNetwork: options.config.allowPrivateNetwork === true,
    });
    const raw = await readResponseTextLimited(response, 4 * 1024 * 1024);
    if (!response.ok) throw new ProviderCallError(providerHttpErrorMessage(response.status, raw,
      [options.config.apiKey ?? ""], response.headers.get("x-request-id")), response.status, false, response.status === 504);
    try {
      return parseModelCatalog(JSON.parse(raw) as unknown);
    } catch (error) {
      if (error instanceof ProviderCallError) throw error;
      throw new ProviderCallError(`Provider returned an invalid model list: ${error instanceof Error ? error.message : String(error)}`, 200, false);
    }
  } catch (error) {
    if (options.signal.aborted) throw options.signal.reason ?? error;
    if (timeoutController.signal.aborted) throw new Error(`Provider model list timed out after ${options.config.timeoutMs}ms.`);
    throw error;
  } finally {
    clearTimeout(timeout);
    combined.dispose();
  }
}

function extractContent(payload: ChatCompletionChunk): string {
  const choice = payload.choices?.[0];
  return choice?.delta?.content ?? choice?.message?.content ?? "";
}

function rejectTruncatedCompletion(finishReason: string | null | undefined): void {
  if (finishReason === "length" || finishReason === "max_tokens") {
    throw new ProviderCallError(
      `模型回复因输出长度上限被截断（finish_reason: ${finishReason}），结果不完整。请减少单批消息数，或在供应商侧提高输出上限。`,
      200,
      false,
    );
  }
}

function parseEventLine(line: string): {
  content: string;
  done: boolean;
  usage?: Record<string, unknown> | undefined;
  finishReason?: string | null | undefined;
} {
  const trimmed = line.trim();
  if (!trimmed.startsWith("data:")) return { content: "", done: false };
  const data = trimmed.slice(5).trim();
  if (!data) return { content: "", done: false };
  if (data === "[DONE]") return { content: "", done: true };
  let payload: ChatCompletionChunk;
  try {
    payload = JSON.parse(data) as ChatCompletionChunk;
  } catch {
    throw new Error(`Provider stream event is not valid JSON: ${data.slice(0, 200)}`);
  }
  return {
    usage: payload.usage,
    finishReason: payload.choices?.[0]?.finish_reason,
    content: extractContent(payload),
    done: false,
  };
}

async function readJsonContent(response: Response): Promise<string> {
  const raw = await readResponseTextLimited(response);
  try {
    const payload = JSON.parse(raw) as ChatCompletionChunk;
    activeTaskBudget.getStore()?.record(payload);
    rejectTruncatedCompletion(payload.choices?.[0]?.finish_reason);
    const content = extractContent(payload);
    if (!content.trim()) throw new Error("Provider returned no structured content.");
    return content;
  } catch (error) {
    if (error instanceof ProviderCallError) throw error;
    throw new ProviderCallError(
      `Provider returned invalid JSON completion data: ${error instanceof Error ? error.message : String(error)}`,
      200,
      false,
    );
  }
}

export async function requestStructuredCompletion(options: {
  config: SecondaryApiConfig;
  messages: PromptMessageInput[] | DiscussionMessage[];
  signal: AbortSignal;
  onProgress?: (receivedCharacters: number) => void;
  onResponse?: () => void;
  onDelta?: ((text: string) => void) | undefined;
}): Promise<string> {
  const { config, messages, signal, onProgress } = options;
  const endpoint = completionUrl(config.baseUrl);
  const timeoutController = new AbortController();
  const timeout = setTimeout(() => {
    timeoutController.abort(new Error(`Provider timed out after ${config.timeoutMs}ms.`));
  }, config.timeoutMs);
  const combined = combineAbortSignals([signal, timeoutController.signal]);

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Accept: config.streaming ? "text/event-stream, application/json" : "application/json",
  };
  if (config.apiKey) headers.Authorization = `Bearer ${config.apiKey}`;

  const body: Record<string, unknown> = {
    model: config.model,
    temperature: config.temperature,
    stream: config.streaming,
    messages,
  };
  if (config.jsonMode) body.response_format = { type: "json_object" };

  let response: Response | undefined;
  try {
    response = await requestProvider(endpoint, {
      method: "POST",
      headers,
      body: JSON.stringify(body),
      signal: combined.signal,
    }, {
      allowPrivateNetwork: config.allowPrivateNetwork === true,
    });

    if (!response.ok) {
      const raw = await readResponseTextLimited(response, 64 * 1024);
      const message = providerHttpErrorMessage(response.status, raw, [config.apiKey ?? ""], response.headers.get("x-request-id"));
      if (response.status === 504) {
        throw new RetrievalProviderError(
          `${message} The request may still have completed and been billed.`,
          { ambiguous: true, status: 504, code: "PROVIDER_HTTP_504" },
        );
      }
      throw new ProviderCallError(
        message,
        response.status,
        response.status === 408 || response.status === 429 || response.status >= 500,
      );
    }

    options.onResponse?.();
    const contentType = response.headers.get("content-type") ?? "";
    if (!config.streaming || contentType.includes("application/json")) {
      return await readJsonContent(response);
    }

    if (!response.body) throw new Error("Provider returned an empty response body.");
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    let content = "";
    let receivedBytes = 0;
    let completed = false;
    let usage: Record<string, unknown> | undefined;
    let finishReason: string | undefined;

    try {
      while (!completed) {
        const { value, done } = await reader.read();
        if (value) {
          receivedBytes += value.byteLength;
          if (receivedBytes > MAX_PROVIDER_RESPONSE_BYTES) {
            throw new ProviderResponseTooLargeError(MAX_PROVIDER_RESPONSE_BYTES);
          }
        }
        buffer += decoder.decode(value, { stream: !done });
        const lines = buffer.split(/\r?\n/);
        buffer = lines.pop() ?? "";
        for (const line of lines) {
          const event = parseEventLine(line);
          usage = event.usage ?? usage;
          finishReason = event.finishReason ?? finishReason;
          content += event.content;
          if (event.content) options.onDelta?.(event.content);
          if (event.done) {
            completed = true;
            break;
          }
        }
        onProgress?.(content.length);
        if (done) break;
      }
      if (!completed && buffer.trim()) {
        const event = parseEventLine(buffer);
        usage = event.usage ?? usage;
        finishReason = event.finishReason ?? finishReason;
        content += event.content;
        if (event.content) options.onDelta?.(event.content);
        completed ||= event.done;
      }
    } finally {
      await reader.cancel().catch(() => undefined);
      reader.releaseLock();
    }
    if (usage) activeTaskBudget.getStore()?.record({ usage });
    rejectTruncatedCompletion(finishReason);
    if (!completed) {
      throw new RetrievalProviderError(
        "The provider stream ended before the OpenAI-compatible [DONE] marker.",
        {
          ambiguous: true,
          status: response.status,
          code: "INCOMPLETE_PROVIDER_STREAM",
        },
      );
    }
    if (!content.trim()) {
      throw new ProviderCallError("Provider returned no structured content.", 200, false);
    }
    return content;
  } catch (error) {
    if (signal.aborted) throw signal.reason ?? error;
    if (error instanceof TaskBudgetExceededError) throw error;
    if (error instanceof RetrievalProviderError) throw error;
    if (error instanceof ProviderUrlPolicyError) {
      throw new RetrievalProviderError(error.message, {
        ambiguous: false,
        code: error.code,
      });
    }
    if (timeoutController.signal.aborted) {
      throw new RetrievalProviderError(
        `Provider timed out after ${config.timeoutMs}ms. The request may still have completed and been billed.`,
        { ambiguous: true, code: "PROVIDER_TIMEOUT" },
      );
    }
    if (error instanceof ProviderResponseTooLargeError) {
      throw new RetrievalProviderError(error.message, {
        ambiguous: true,
        status: response?.status,
        code: "PROVIDER_RESPONSE_TOO_LARGE",
      });
    }
    const code = networkErrorCode(error);
    if (!response && ["ECONNREFUSED", "ENOTFOUND", "EAI_AGAIN", "ERR_INVALID_URL"].includes(code)) {
      throw new RetrievalProviderError(
        `Provider connection failed before a response was accepted${code ? ` (${code})` : ""}.`,
        { ambiguous: false, code: code || "PROVIDER_CONNECTION_FAILED" },
      );
    }
    const detail = error instanceof Error ? error.message : String(error);
    throw new RetrievalProviderError(
      `${response ? "The provider response ended" : "The provider connection ended"} before a complete result was decoded${detail ? `: ${detail}` : "."}`,
      {
        ambiguous: true,
        ...(response ? { status: response.status } : {}),
        code: response ? "INCOMPLETE_PROVIDER_STREAM" : "PROVIDER_CONNECTION_AMBIGUOUS",
      },
    );
  } finally {
    clearTimeout(timeout);
    combined.dispose();
  }
}
