import { businessRegex, type BusinessRegexId, type BusinessRegexSettings } from "./business-regex";
import { declaredAliases } from "./extraction-context";
import type { MemoryRow, MemoryTypeDefinition } from "./domain";
import { parseProviderJsonObject } from "../server/services/provider-json";
import { statusTriggerQueries } from "../extension/continuity-recall";
import { supplementQueryVariants } from "./recall-query";
import { inspectSummaryCoverage, compareSummaryCandidates } from "../extension/summary/coverage";

export const businessTasks = {
  aliases: (rows: MemoryRow[], types: MemoryTypeDefinition[], rules: BusinessRegexSettings) =>
    Object.fromEntries(rows.map((row) => [row.id, declaredAliases(row, types, rules)])),
  provider: parseProviderJsonObject,
  triggers: statusTriggerQueries,
  variants: supplementQueryVariants,
  coverage: inspectSummaryCoverage,
  compare: compareSummaryCandidates,
  preview: (id: BusinessRegexId, text: string, rules: BusinessRegexSettings) => {
    const regex = businessRegex(id, rules);
    const all = new RegExp(regex.source, regex.flags.includes("g") ? regex.flags : `${regex.flags}g`);
    const matches = [];
    for (const match of text.matchAll(all)) {
      matches.push({ index: match.index, text: match[0], groups: match.slice(1) });
      if (matches.length === 100) break;
    }
    return matches;
  },
};
export type BusinessTask = keyof typeof businessTasks;
export type BusinessArgs<K extends BusinessTask> = Parameters<typeof businessTasks[K]>;
export type BusinessResult<K extends BusinessTask> = ReturnType<typeof businessTasks[K]>;
export interface BusinessTaskRequest<K extends BusinessTask = BusinessTask> { task: K; args: BusinessArgs<K> }
const taskRules: Record<BusinessTask, readonly BusinessRegexId[]> = {
  aliases: ["aliasName", "aliasId", "aliasSeparator"], provider: ["reasoningClosed", "reasoningOpen"],
  triggers: ["sceneEmpty", "planDone", "planPending"], variants: ["querySeparator"],
  coverage: ["coverageWords", "coverageHan"], compare: ["coverageWords", "coverageHan"], preview: [],
};
export function needsBusinessWorker<K extends BusinessTask>(request: BusinessTaskRequest<K>): boolean {
  if (request.task === "preview" || request.task === "provider") return true;
  const rules = request.args.at(-1);
  return !!rules && typeof rules === "object" && taskRules[request.task].some((id) => Object.hasOwn(rules, id));
}
export function executeBusinessTask<K extends BusinessTask>(request: BusinessTaskRequest<K>): BusinessResult<K> {
  // The public task/args pair ties the selected function to its tuple at the boundary.
  const fn = businessTasks[request.task] as unknown as (...args: BusinessArgs<K>) => BusinessResult<K>;
  return fn(...request.args);
}
