import type {
  ExtractionRequest,
  ExtractionResult,
  MemoryExtractionOperation,
  MemoryRow,
  MemoryTypeDefinition,
  PromptMessageInput,
} from "../../shared/domain";
import {
  extractionOperationSchema,
  validateMemoryValues,
} from "../../shared/schemas";
import {
  structuredExtractionContextHash,
  structuredExtractionMessageHash,
} from "../../shared/extraction-core";
import type { JobContext } from "../jobs/job-manager";
import {
  extractionContextRows,
  extractionProviderMessages,
  extractionRowReferences,
  unavailableExtractionRowReason,
} from "../../shared/extraction-references";
import { GenerationService } from "./generation-service";
import { parseConfiguredProviderJson, runBusinessTask } from "./business-regex";
import { extractionNameCollision } from "../../shared/extraction-context";

export function buildExtractionMessages(request: ExtractionRequest): PromptMessageInput[] {
  return extractionProviderMessages(request);
}

function duplicateDataName(
  rows: MemoryRow[],
  typeId: string,
  dataName: string,
  exceptRowId?: string,
): boolean {
  const normalized = dataName.trim().toLocaleLowerCase();
  return rows.some(
    (row) => row.typeId === typeId
      && row.id !== exceptRowId
      && row.dataName.trim().toLocaleLowerCase() === normalized,
  );
}

function validateOperation(
  operation: MemoryExtractionOperation,
  types: Map<string, MemoryTypeDefinition>,
  rows: MemoryRow[],
  messageIds: string[],
  initialRows: MemoryRow[],
  identityRows: MemoryRow[] = rows,
): void {
  const type = types.get(operation.typeId);
  if (!type) throw new Error(`Operation references an unavailable type: ${operation.typeId}`);

  if (operation.action === "add") {
    if (duplicateDataName(identityRows, type.id, operation.dataName)) {
      throw new Error(`Data name already exists in ${type.name}: ${operation.dataName}`);
    }
    const values = validateMemoryValues(type.columns, operation.values);
    rows.push({
      ...(operation.aliases ? { aliases: operation.aliases } : {}),
      ...(operation.continuity ? { continuity: operation.continuity } : {}),
      id: `pending_${rows.length}`,
      typeId: type.id,
      dataName: operation.dataName,
      keywords: operation.keywords,
      status: operation.status,
      values,
      enabled: true,
      source: { kind: "extraction", messageIds: [...messageIds] },
      revision: 1,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    });
    return;
  }

  const rowIndex = rows.findIndex((row) => row.id === operation.rowId);
  const current = rows[rowIndex];
  if (!initialRows.some((row) => row.id === operation.rowId) || !current || current.typeId !== type.id) {
    throw new Error(unavailableExtractionRowReason(operation.rowId, type.id, initialRows, rows));
  }
  if (operation.action === "delete") {
    rows.splice(rowIndex, 1);
    return;
  }

  const dataName = operation.changes.dataName ?? current.dataName;
  if (duplicateDataName(identityRows, type.id, dataName, current.id)) {
    throw new Error(`Data name already exists in ${type.name}: ${dataName}`);
  }
  const mergedValues = {
    ...current.values,
    ...(operation.changes.values ?? {}),
  };
  rows[rowIndex] = {
    ...current,
    ...(operation.changes.aliases ? { aliases: operation.changes.aliases } : {}),
    ...(operation.changes.continuity ? { continuity: { ...current.continuity, ...operation.changes.continuity } } : {}),
    dataName,
    keywords: operation.changes.keywords ?? current.keywords,
    status: operation.changes.status ?? current.status,
    values: validateMemoryValues(type.columns, mergedValues),
  };
}

function parseOperation(value: unknown): { operation?: MemoryExtractionOperation; reason?: string } {
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed.startsWith("{") || !trimmed.endsWith("}")) {
      return { reason: "Operation must be a JSON object; the model returned a string." };
    }
    try {
      return parseOperation(JSON.parse(trimmed));
    } catch {
      return { reason: "Operation is a string but is not valid JSON." };
    }
  }
  const result = extractionOperationSchema.safeParse(value);
  if (result.success) return { operation: result.data };
  const issue = result.error.issues[0]!;
  const path = issue.path.length > 0 ? ` at ${issue.path.join(".")}` : "";
  return {
    reason: `Invalid operation${path}: ${issue?.message ?? "the object does not match the required protocol."}`,
  };
}

export class ExtractionService {
  constructor(private readonly generation: GenerationService) {}

  async extract(
    request: ExtractionRequest,
    context: JobContext,
  ): Promise<ExtractionResult> {
    if (await structuredExtractionMessageHash(request.messages) !== request.batch.sourceHash) {
      throw Object.assign(new Error("Extraction batch source hash does not match its messages."), {
        statusCode: 400,
        code: "EXTRACTION_SOURCE_HASH_MISMATCH",
      });
    }
    if (await structuredExtractionContextHash(request.types, request.rows) !== request.batch.contextHash) {
      throw Object.assign(new Error("Extraction context hash does not match its types and rows."), {
        statusCode: 400,
        code: "EXTRACTION_CONTEXT_HASH_MISMATCH",
      });
    }
    const types = new Map(request.types.map((type) => [type.id, type]));
    const simulatedRows = structuredClone(request.rows);
    const rowReferences = extractionRowReferences(request.rows);
    const aliasIndex = await runBusinessTask({ task: "aliases", args: [request.rows, request.types, request.businessRegex ?? {}] }, context.signal);
    const indexedRows = new Map(simulatedRows.map((row) => [row.id, row]));
    const selectedRows = extractionContextRows(request, aliasIndex).rows;
    const messageIds = request.messages.map((message) => message.id);
    const providerMessages = extractionProviderMessages(request, aliasIndex);

    context.report(0.1, "Waiting for secondary API");
    const generated = await this.generation.run({
      workflow: "extraction",
      group: request.generationGroup,
      policy: request.failoverPolicy,
      resumeAfterEndpointId: request.resumeAfterEndpointId,
      messages: providerMessages,
      context,
    });
    if (generated.decisionRequired) {
      return {
        outcome: "decision_required",
        operations: [],
        rejectedOperations: [],
        reviewItems: [],
        attempts: generated.attempts,
        decisionRequired: generated.decisionRequired,
      };
    }
    if (generated.state !== "succeeded" || !generated.value) {
      throw Object.assign(new Error(generated.message ?? "All generation endpoints failed."), {
        statusCode: 502,
        code: "GENERATION_ENDPOINTS_FAILED",
      });
    }

    context.report(0.8, "Validating proposed memory operations");
    let parsedPayload: Record<string, unknown>;
    try {
      parsedPayload = await parseConfiguredProviderJson(generated.value, "结构化提取", "operations", request.businessRegex, context.signal);
    } catch (error) {
      throw Object.assign(error instanceof Error ? error : new Error(String(error)), {
        statusCode: 502,
        code: "INVALID_EXTRACTION_RESPONSE",
      });
    }
    const rawOperations = parsedPayload.operations;
    if (!Array.isArray(rawOperations)) {
      throw Object.assign(new Error("Extraction response field operations must be an array."), {
        statusCode: 502,
        code: "INVALID_EXTRACTION_RESPONSE",
      });
    }
    if (rawOperations.length > 500) {
      throw Object.assign(new Error("Extraction response contains more than 500 operations."), {
        statusCode: 502,
        code: "INVALID_EXTRACTION_RESPONSE",
      });
    }
    const operations: MemoryExtractionOperation[] = [];
    const rejectedOperations: ExtractionResult["rejectedOperations"] = [];
    const reviewItems: ExtractionResult["reviewItems"] = [];
    const proposed = rawOperations.map((candidate) => {
      const parsed = parseOperation(candidate);
      const operation = parsed.operation?.action === "add" ? parsed.operation
        : parsed.operation ? {
          ...parsed.operation,
          rowId: rowReferences.get(parsed.operation.rowId) ?? parsed.operation.rowId,
        } : undefined;
      return { candidate, operation, reason: parsed.reason };
    });
    // Only cleaning can transfer identities from rows deleted in this same batch.
    const deletedRowIds = new Set(request.batch.mode === "cleaning" ? proposed.flatMap(({ operation }) =>
      operation?.action === "delete" && types.has(operation.typeId)
        && selectedRows.some((row) => row.id === operation.rowId && row.typeId === operation.typeId)
        ? [operation.rowId] : []) : []);

    for (const [index, { candidate, operation, reason: parseReason }] of proposed.entries()) {
      if (!operation) {
        const reason = parseReason ?? "Invalid extraction operation.";
        rejectedOperations.push({ operation: candidate, reason });
        reviewItems.push({ index, state: "rejected", operation: candidate, reason });
        continue;
      }
      const identityRows = deletedRowIds.size
        ? simulatedRows.filter((row) => !deletedRowIds.has(row.id)) : simulatedRows;
      const changedRows = identityRows.filter((row) => indexedRows.get(row.id) !== row);
      if (changedRows.length) {
        Object.assign(aliasIndex, await runBusinessTask({ task: "aliases", args: [changedRows, request.types, request.businessRegex ?? {}] }, context.signal));
        for (const row of changedRows) indexedRows.set(row.id, row);
      }
      context.signal.throwIfAborted();
      try {
        const attributes = operation.action === "add" ? operation.continuity
          : operation.action === "update" ? operation.changes.continuity : undefined;
        if (attributes && !request.extractAttributes) throw new Error("时间与认知属性提取未启用。");
        if (operation.action !== "add" && request.contextPolicy?.enabled
          && !selectedRows.some((row) => row.id === operation.rowId)) {
          throw new Error("该记录未提供完整详情；请扩大写表上下文或手动处理，未修改或删除该记录。");
        }
        const name = operation.action === "add" ? operation.dataName
          : operation.action === "update" ? operation.changes.dataName : undefined;
        if (name && extractionNameCollision(identityRows, request.types, operation.typeId, name,
          operation.action === "update" ? operation.rowId : undefined, aliasIndex)) {
          throw new Error(`名称或已声明别名已存在：${name}。请核对身份，未自动合并实体。`);
        }
        const aliases = operation.action === "add" ? operation.aliases : operation.action === "update" ? operation.changes.aliases : undefined;
        if (aliases?.some((alias) => extractionNameCollision(identityRows, request.types, operation.typeId, alias,
          operation.action === "update" ? operation.rowId : undefined, aliasIndex))) throw new Error("别名与已有实体冲突，请人工核对，未自动合并。");
        validateOperation(operation, types, simulatedRows, messageIds, request.rows, identityRows);
        operations.push(operation);
        reviewItems.push({ index, state: "valid", operation });
      } catch (error) {
        const reason = error instanceof Error ? error.message : String(error);
        rejectedOperations.push({
          operation,
          reason,
        });
        reviewItems.push({ index, state: "rejected", operation, reason });
      }
      context.report(
        0.8 + ((index + 1) / Math.max(rawOperations.length, 1)) * 0.19,
        `Validating operation ${index + 1}/${rawOperations.length}`,
      );
    }

    return {
      outcome: "completed",
      operations,
      rejectedOperations,
      reviewItems,
      attempts: generated.attempts,
    };
  }
}
