import { z } from "zod";

// Story dates may use unrelated calendars, eras, ranges or relative descriptions.
// They are text, not Gregorian dates or sortable timestamps.
export const storyTimeSchema = z.string().trim().max(4000);
export const continuitySchema = z.object({
  eventTime: storyTimeSchema.optional(),
  learnedTime: storyTimeSchema.optional(),
  validFrom: storyTimeSchema.optional(),
  validUntil: storyTimeSchema.optional(),
  validity: z.enum(["current", "historical", "superseded"]).optional(),
  changeKind: z.enum(["fact_change", "knowledge_change", "canon_correction", "unclassified"]).optional(),
  note: z.string().max(4000).optional(),
  knowledge: z.array(z.object({
    character: z.string().trim().min(1).max(240),
    state: z.enum(["known", "believed", "suspected", "misunderstood", "unknown"]),
    claim: z.string().trim().min(1).max(4000),
    learnedTime: storyTimeSchema.optional(),
  }).strict()).max(50).optional(),
}).strict();
export type ContinuityAttributes = z.infer<typeof continuitySchema>;
export const aliasSchema = z.array(z.string().trim().min(1).max(240)).max(100);

export const continuitySettingsSchema = z.object({
  extractAttributes: z.boolean().default(false),
  triggers: z.object({
    enabled: z.boolean().default(false), maxQueries: z.number().int().min(1).max(4).default(2),
    nearDays: z.number().int().min(0).max(30).default(3),
  }).default({ enabled: false, maxQueries: 2, nearDays: 3 }),
  supplement: z.object({
    auto: z.boolean().default(false), maxRequests: z.number().int().min(0).max(3).default(1),
    maxWaitMs: z.number().int().min(1000).max(120000).default(15000),
    maxItems: z.number().int().min(1).max(20).default(3),
    minimumHits: z.number().int().min(0).max(100).default(2),
    allowPaid: z.boolean().default(false),
  }).default({ auto: false, maxRequests: 1, maxWaitMs: 15000, maxItems: 3, minimumHits: 2, allowPaid: false }),
});
export type ContinuitySettings = z.infer<typeof continuitySettingsSchema>;
export const DEFAULT_CONTINUITY = continuitySettingsSchema.parse({});

export function currentFact(attributes?: ContinuityAttributes): boolean {
  return attributes?.validity !== "superseded" && attributes?.validity !== "historical";
}
const states = { known: "已知", believed: "相信", suspected: "怀疑", misunderstood: "误解", unknown: "未知" };
export function renderContinuity(value?: ContinuityAttributes): string {
  if (!value) return "";
  const labels = { current: "当前资料", historical: "历史经历，非当前事实", superseded: "已更正失效，非当前事实" };
  return [
    value.eventTime && `事件发生时间：${value.eventTime}`,
    value.learnedTime && `信息得知时间：${value.learnedTime}`,
    value.validFrom && `事实有效起点：${value.validFrom}`,
    value.validUntil && `事实有效终点：${value.validUntil}`,
    value.validity && labels[value.validity],
    value.note && `限定说明：${value.note}`,
    ...(value.knowledge ?? []).map((item) => `【角色认知：${item.character} / ${states[item.state]}${item.learnedTime ? ` / 得知于 ${item.learnedTime}` : ""}】${item.claim}`),
  ].filter(Boolean).join("\n");
}

export const CONTINUITY_EXTRACTION_GUIDE = `已开启时间与认知属性。每条记录可以附带一个 continuity 对象，其中每个字段都是可选的；没有依据就省略，不补造精度。

- eventTime：事件发生的时间；learnedTime：信息被得知的时间；validFrom、validUntil：事实有效的起止时间。
- changeKind：记录的是哪种变化，只选一个代码——fact_change（事实发生变化）、knowledge_change（角色的认知发生变化）、canon_correction（更正旧设定）、unclassified（未分类）。无法判断时用 unclassified 或省略。
- validity：只选一个代码——current（当前有效）、historical（历史经历）、superseded（已被更正而失效）。只有整条记录都失效时才用 superseded。
- knowledge：角色对某条具体说法的认知，每项含 character（角色）、state（状态）、claim（说法），可选 learnedTime。state 只选一个代码——known（已知）、believed（相信）、suspected（怀疑）、misunderstood（误解）、unknown（未知）。
- note：其他限定说明。
- 字段名和代码保留英文；character、claim、note 用中文。
- 所有时间字段保留故事原文的历法、纪元、精度、区间和模糊描述，例如“辉轮历270年”“协定历270年”“新元三年冬至次年春”。不强制公历，不补零、不换算历法，不把不同历法的同年号视为同一年。没有依据就省略时间字段。

认知状态针对具体说法，而不是整个场景。后来才得知的信息，不等于早就知道。区分实际发生的变化与对旧记录的更正。省略这个对象不会改变已有的属性。

continuity 直接写在它所属的那个对象里，不另包一层：add 操作中与 values 并列；update 操作中写在 changes 里，与 values 并列；剧情总结中写在每条记录里，与 title、content 并列。

虚构格式示例：
{"action":"add","typeId":"items","dataName":"旧潮罗盘","keywords":["旧潮罗盘"],"values":{"owner":"洛禾"},"continuity":{"eventTime":"2087-04","validity":"current"}}
{"action":"update","typeId":"people","rowId":"R1","changes":{"values":{"identity":"灯塔测绘员"},"continuity":{"changeKind":"knowledge_change","knowledge":[{"character":"洛禾","state":"suspected","claim":"罗盘的封条可能被更换"}]}}}`;
