import { summaryPayloadSchema } from "../../shared/schemas";
import { parseProviderJsonObject } from "./provider-json";

function object(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

const enumAliases: Record<string, Record<string, string>> = {
  changeKind: {
    fact_change: "fact_change", knowledge_change: "knowledge_change", canon_correction: "canon_correction", unclassified: "unclassified",
    事实变化: "fact_change", 事实发生变化: "fact_change", 认知变化: "knowledge_change", 角色认知变化: "knowledge_change",
    设定更正: "canon_correction", 更正旧设定: "canon_correction", 未分类: "unclassified",
  },
  validity: {
    current: "current", historical: "historical", superseded: "superseded",
    当前有效: "current", 历史经历: "historical", 已被更正失效: "superseded",
  },
  state: {
    known: "known", believed: "believed", suspected: "suspected", misunderstood: "misunderstood", unknown: "unknown",
    已知: "known", 相信: "believed", 怀疑: "suspected", 误解: "misunderstood", 未知: "unknown",
  },
};

/** Normalize provider formatting only; persisted data still uses the strict schemas. */
export function parseSummaryOutput(raw: string) {
  let payload: unknown;
  try { payload = parseProviderJsonObject(raw, "总结切片", "summaries"); }
  catch (error) {
    throw new Error(`${error instanceof Error ? error.message : String(error)} 本次未写入切片、未推进检查点。`);
  }
  return parseSummaryPayload(payload);
}

export function parseSummaryPayload(payload: unknown) {
  let normalizedFields = 0;
  if (object(payload) && Array.isArray(payload.summaries)) {
    for (const slice of payload.summaries) {
      if (!object(slice)) continue;
      if (!object(slice.continuity)) continue;
      const continuity = slice.continuity;
      const notes: string[] = [];
      const normalizeEnum = (target: Record<string, unknown>, field: string) => {
        const value = target[field];
        if (typeof value !== "string") return;
        const key = value.trim().toLowerCase().replace(/[\s-]+/g, "_");
        const aliases = enumAliases[field];
        const mapped = aliases && Object.hasOwn(aliases, key) ? aliases[key] : undefined;
        if (mapped !== undefined) {
          if (mapped !== value) { target[field] = mapped; normalizedFields++; }
        } else if (field === "changeKind") {
          // A free-form category is not evidence of a canon correction or factual change.
          target[field] = "unclassified";
          notes.push(`模型原始变化分类：${value}`);
          normalizedFields++;
        }
      };
      normalizeEnum(continuity, "changeKind");
      normalizeEnum(continuity, "validity");
      if (Array.isArray(continuity.knowledge)) for (const knowledge of continuity.knowledge) {
        if (!object(knowledge)) continue;
        normalizeEnum(knowledge, "state");
      }
      if (notes.length && (continuity.note === undefined || typeof continuity.note === "string")) {
        continuity.note = [continuity.note, ...notes].filter(Boolean).join("\n");
      }
    }
  }
  const result = summaryPayloadSchema.safeParse(payload);
  if (!result.success) {
    const issues = result.error.issues.slice(0, 10).map((issue) => {
      let value: unknown = payload;
      for (const part of issue.path) {
        value = value !== null && typeof value === "object" ? Reflect.get(value, part) : undefined;
      }
      const field = issue.path.at(-1);
      const showValue = ["timestamp", "eventTime", "learnedTime", "validFrom", "validUntil", "changeKind", "validity", "state"].includes(String(field));
      const actual = showValue ? ` (received ${JSON.stringify(value)?.slice(0, 160) ?? "undefined"})` : "";
      return `${issue.path.join(".")}: ${issue.message}${actual}`;
    });
    throw new Error(`总结输出校验失败；本次未写入切片、未推进检查点。\n${issues.join("\n")}`
      + (result.error.issues.length > 10 ? `\n另有 ${result.error.issues.length - 10} 项校验错误。` : ""));
  }
  return { ...result.data, normalizedFields };
}
