import { z } from "zod";

export const creativePreferenceSchema = z.object({
  id: z.string().min(1).max(120),
  title: z.string().trim().min(1).max(120),
  category: z.enum(["expression", "pace", "boundary", "other"]),
  rule: z.string().trim().min(1).max(5000),
  condition: z.string().max(2000),
  source: z.string().max(2000),
  confirmed: z.boolean(),
  enabled: z.boolean(),
  updatedAt: z.string().datetime(),
}).strict();

export const creativePreferencesSchema = z.object({
  enabled: z.boolean(),
  rules: z.array(creativePreferenceSchema).max(100),
}).strict().superRefine((value, ctx) => {
  if (new Set(value.rules.map((rule) => rule.id)).size !== value.rules.length)
    ctx.addIssue({ code: "custom", path: ["rules"], message: "创作偏好 ID 不得重复。" });
});

export type CreativePreference = z.infer<typeof creativePreferenceSchema>;
export type CreativePreferences = z.infer<typeof creativePreferencesSchema>;
export const EMPTY_CREATIVE_PREFERENCES: CreativePreferences = { enabled: false, rules: [] };

export function renderCreativePreferences(global: CreativePreferences, chat: CreativePreferences): string {
  const parts = [["全局", global], ["当前聊天", chat]] as const;
  const rules = parts.flatMap(([scope, settings]) => settings.enabled ? settings.rules
    .filter((rule) => rule.confirmed && rule.enabled).map((rule) =>
      `- [${scope}] ${rule.title}：${rule.condition.trim() ? `仅在「${rule.condition.trim()}」时，` : ""}${rule.rule}`) : []);
  if (!rules.length) return "";
  return `<echoes_creative_preferences>
以下是用户确认的创作要求，不是世界事实或已发生的剧情。条件成立时应用；与用户本轮的要求冲突时，以本轮要求为准；当前聊天的要求优先于全局要求。
${rules.join("\n")}
</echoes_creative_preferences>`;
}
